span","_key":"a47","text":"13"}]},{"children":[{"_type":"span","_key":"a48","text":"27"}]},{"children":[{"_type":"span","_key":"a49","text":"The Ant"}]},{"children":[{"_type":"span","_key":"a4a","text":"T.S."}]}]},{"_key":"a4b","style":"data","cells":[{"children":[{"_type":"span","_key":"a4c","text":"14"}]},{"children":[{"_type":"span","_key":"a4d","text":"28"}]},{"children":[{"_type":"span","_key":"a4e","text":"History"}]},{"children":[{"_type":"span","_key":"a4f","text":"T.S.M."}]}]},{"_key":"a4g","style":"data","cells":[{"children":[{"_type":"span","_key":"a4h","text":"15"}]},{"children":[{"_type":"span","_key":"a4i","text":"29"}]},{"children":[{"_type":"span","_key":"a4j","text":"The Spider"}]},{"children":[{"_type":"span","_key":"a4k","text":"A.L.M."}]}]},{"_key":"a4l","style":"data","cells":[{"children":[{"_type":"span","_key":"a4m","text":"16"}]},{"children":[{"_type":"span","_key":"a4n","text":"30"}]},{"children":[{"_type":"span","_key":"a4o","text":"The Romans"}]},{"children":[{"_type":"span","_key":"a4p","text":"A.L.M."}]}]},{"_key":"a4q","style":"data","cells":[{"children":[{"_type":"span","_key":"a4r","text":"17"}]},{"children":[{"_type":"span","_key":"a4s","text":"31"}]},{"children":[{"_type":"span","_key":"a4t","text":"Luqmaan"}]},{"children":[{"_type":"span","_key":"a4u","text":"A.L.M."}]}]},{"_key":"a4v","style":"data","cells":[{"children":[{"_type":"span","_key":"a4w","text":"18"}]},{"children":[{"_type":"span","_key":"a4x","text":"32"}]},{"children":[{"_type":"span","_key":"a4y","text":"Prostration"}]},{"children":[{"_type":"span","_key":"a4z","text":"A.L.M."}]}]},{"_key":"a50","style":"data","cells":[{"children":[{"_type":"span","_key":"a51","text":"19"}]},{"children":[{"_type":"span","_key":"a52","text":"36"}]},{"children":[{"_type":"span","_key":"a53","text":"Y.S."}]},{"children":[{"_type":"span","_key":"a54","text":"Y.S."}]}]},{"_key":"a55","style":"data","cells":[{"children":[{"_type":"span","_key":"a56","text":"20"}]},{"children":[{"_type":"span","_key":"a57","text":"38"}]},{"children":[{"_type":"span","_key":"a58","text":"S."}]},{"children":[{"_type":"span","_key":"a59","text":"S."}]}]},{"_key":"a5a","style":"data","cells":[{"children":[{"_type":"span","_key":"a5b","text":"21"}]},{"children":[{"_type":"span","_key":"a5c","text":"40"}]},{"children":[{"_type":"span","_key":"a5d","text":"Forgiver"}]},{"children":[{"_type":"span","_key":"a5e","text":"H.M."}]}]},{"_key":"a5f","style":"data","cells":[{"children":[{"_type":"span","_key":"a5g","text":"22"}]},{"children":[{"_type":"span","_key":"a5h","text":"41"}]},{"children":[{"_type":"span","_key":"a5i","text":"Elucidated"}]},{"children":[{"_type":"span","_key":"a5j","text":"H.M."}]}]},{"_key":"a5k","style":"data","cells":[{"children":[{"_type":"span","_key":"a5l","text":"23"}]},{"children":[{"_type":"span","_key":"a5m","text":"42"}]},{"children":[{"_type":"span","_key":"a5n","text":"Consultation"}]},{"children":[{"_type":"span","_key":"a5o","text":"H.M. 'A.S.Q."}]}]},{"_key":"a5p","style":"data","cells":[{"children":[{"_type":"span","_key":"a5q","text":"24"}]},{"children":[{"_type":"span","_key":"a5r","text":"43"}]},{"children":[{"_type":"span","_key":"a5s","text":"Ornaments"}]},{"children":[{"_type":"span","_key":"a5t","text":"H.M."}]}]},{"_key":"a5u","style":"data","cells":[{"children":[{"_type":"span","_key":"a5v","text":"25"}]},{"children":[{"_type":"span","_key":"a5w","text":"44"}]},{"children":[{"_type":"span","_key":"a5x","text":"Smoke"}]},{"children":[{"_type":"span","_key":"a5y","text":"H.M."}]}]},{"_key":"a5z","style":"data","cells":[{"children":[{"_type":"span","_key":"a60","text":"26"}]},{"children":[{"_type":"span","_key":"a61","text":"45"}]},{"children":[{"_type":"span","_key":"a62","text":"Kneeling"}]},{"children":[{"_type":"span","_key":"a63","text":"H.M."}]}]},{"_key":"a64","style":"data","cells":[{"children":[{"_type":"span","_key":"a65","text":"27"}]},{"children":[{"_type":"span","_key":"a66","text":"46"}]},{"children":[{"_type":"span","_key":"a67","text":"The Dunes"}]},{"children":[{"_type":"span","_key":"a68","text":"H.M."}]}]},{"_key":"a69","style":"data","cells":[{"children":[{"_type":"span","_key":"a6a","text":"28"}]},{"children":[{"_type":"span","_key":"a6b","text":"50"}]},{"children":[{"_type":"span","_key":"a6c","text":"Q."}]},{"children":[{"_type":"span","_key":"a6d","text":"Q."}]}]},{"_key":"a6e","style":"data","cells":[{"children":[{"_type":"span","_key":"a6f","text":"29"}]},{"children":[{"_type":"span","_key":"a6g","text":"68"}]},{"children":[{"_type":"span","_key":"a6h","text":"The Pen"}]},{"children":[{"_type":"span","_key":"a6i","text":"NuN"}]}]}]},{"_type":"appendixDivider","_key":"a6k","title":{"children":[{"_type":"span","_key":"a6l","text":"Historical Background"}]},"centered":true},{"_type":"block","_key":"a6p","style":"normal","children":[{"_type":"span","_key":"a6m","text":"In 1968, I realized that the existing English translations of the Quran did not present the truthful message of God’s Final Testament. For example, the two most popular translators, Yusuf Ali and Marmaduke Pickthall, could not overcome their corrupted religious traditions when it came to the Quran’s great criterion in "},{"_type":"quranRef","_key":"a6n","reference":"39:45"},{"_type":"span","_key":"a6o","text":"."}]},{"_type":"appendixCallout","_key":"a6q","tone":"muted","style":"attributionStacked","content":[{"_type":"block","_key":"a6s","style":"normal","children":[{"_type":"span","_key":"a6r","text":"When God ALONE is mentioned, the hearts of those who do not believe in the Hereafter shrink with aversion. But when others are mentioned beside Him, they rejoice. [39:45]"}]}],"reveal":false},{"_type":"block","_key":"a6w","style":"normal","children":[{"_type":"span","_key":"a6t","text":"Yusuf Ali omitted the crucial word “ALONE” from his translation, and altered the rest of the verse by inserting the word “(gods).” Thus, he utterly destroyed this most important Quranic criterion. He translated "},{"_type":"quranRef","_key":"a6u","reference":"39:45"},{"_type":"span","_key":"a6v","text":" as follows:"}]},{"_type":"appendixCallout","_key":"a6x","tone":"muted","style":"attributionStacked","content":[{"_type":"block","_key":"a6z","style":"normal","children":[{"_type":"span","_key":"a6y","text":"“When God, the One and Only, is mentioned, the hearts of those who believe not in the Hereafter are filled with disgust and horror; but when (gods) other than He are mentioned, behold, they are filled with joy.” [39:45] (according to A. Yusuf Ali)"}]}],"reveal":false},{"_type":"block","_key":"a71","style":"normal","children":[{"_type":"span","_key":"a70","text":"The expression “When God, the One and Only, is mentioned,” is not the same as saying, “When God alone is mentioned.” One can mention “God, the One and Only,” and also mention Muhammad or Jesus, and no one will be upset. But if “God ALONE is mentioned,” you cannot mention anyone else, and a lot of people — those who idolize Muhammad or Jesus — will be upset. Thus, Yusuf Ali could not bring himself to present the truth of the Quran, if it exposed his corrupted belief."}]},{"_type":"block","_key":"a75","style":"normal","children":[{"_type":"span","_key":"a72","text":"Marmaduke Pickthall translated “ALONE” correctly, but destroyed the criterion by inserting his personal belief in parentheses; he translated "},{"_type":"quranRef","_key":"a73","reference":"39:45"},{"_type":"span","_key":"a74","text":" as follows:"}]},{"_type":"appendixCallout","_key":"a76","tone":"muted","style":"attributionStacked","content":[{"_type":"block","_key":"a78","style":"normal","children":[{"_type":"span","_key":"a77","text":"“And when Allah alone is mentioned, the hearts of those who believe not in the Hereafter are repelled, and when those (whom they worship) beside Him are mentioned, behold! they are glad.” [39:45] (according to Marmaduke Pickthall)"}]}],"reveal":false},{"_type":"block","_key":"a7a","style":"normal","children":[{"_type":"span","_key":"a79","text":"When I saw the truth of God’s word thus distorted, I decided to translate the Quran, at least for the benefit of my own children. Since I was a chemist by profession, and despite my extensive religious background — my father was a renowned Sufi leader in Egypt — I vowed to God that I would not move from one verse to the next unless I fully understood it."}]},{"_type":"block","_key":"a7c","style":"normal","children":[{"_type":"span","_key":"a7b","text":"I purchased all the available books of Quranic translations and exegeses (Tafseer) I could find, placed them on a large table, and began my translation. The first sura, The Key, was completed in a few days. The first verse in Sura 2 is “A.L.M.” The translation of this verse took four years, and coincided with the divine unveiling of “the secret,” the great mathematical Miracle of the Quran."}]},{"_type":"block","_key":"a7e","style":"normal","children":[{"_type":"span","_key":"a7d","text":"The books of Quranic exegeses unanimously agreed that “no one knows the meaning or significance of the Quranic Initials A.L.M., or any other initials.” I decided to write the Quran into the computer, analyze the whole text, and see if there were any mathematical correlations among these Quranic initials."}]},{"_type":"block","_key":"a7g","style":"normal","children":[{"_type":"span","_key":"a7f","text":"I used a time-share terminal, connected by telephone to a giant computer. To test my hypothesis, I decided to look at the single-lettered Quranic Initials — “Q” (Qaaf) of Suras 42 and 50, “S” (Saad) of Suras 7, 19, and 38, and “N” (Noon) of Sura 68. As detailed in my first book MIRACLE OF THE QURAN: SIGNIFICANCE OF THE MYSTERIOUS ALPHABETS (Islamic Productions, 1973), many previous attempts to unravel the mystery had failed."}]},{"_type":"appendixDivider","_key":"a7h","title":{"children":[{"_type":"span","_key":"a7i","text":"The Quranic Initial “Q” (Qaaf)"}]},"centered":true},{"_type":"block","_key":"a7k","style":"normal","children":[{"_type":"span","_key":"a7j","text":"The computer data showed that the text of the only Q-initialed suras, 42 and 50, contained the same number of Q’s, 57 and 57. That was the first hint that a deliberate mathematical system may exist in the Quran."}]},{"_type":"block","_key":"a7m","style":"normal","children":[{"_type":"span","_key":"a7l","text":"Sura 50 is entitled “Q,” prefixed with “Q,” and the first verse reads, “Q, and the glorious Quran.” This indicated that “Q” stands for “Quran,” and the total number of Q’s in the two Q-initialed suras represents the Quran’s 114 suras (57+57 = 114 = 19×6). This idea was strengthened by the fact that “the Quran” occurs in the Quran 57 times."}]},{"_type":"block","_key":"a7o","style":"normal","children":[{"_type":"span","_key":"a7n","text":"The Quran is described in Sura “Q” as “Majid” (glorious), and the Arabic word “Majid” has a gematrical value of 57: M(40) + J(3) + I(10) + D(4) = 57."}]},{"_type":"block","_key":"a7q","style":"normal","children":[{"_type":"span","_key":"a7p","text":"Sura 42 consists of 53 verses, and 42+53 = 95 = 19×5."}]},{"_type":"block","_key":"a7s","style":"normal","children":[{"_type":"span","_key":"a7r","text":"Sura 50 consists of 45 verses, and 50+45 = 95, same total as in Sura 42."}]},{"_type":"block","_key":"a7u","style":"normal","children":[{"_type":"span","_key":"a7t","text":"By counting the letter “Q” in every “Verse 19” throughout the Quran, the total count comes to 76, 19×4. Here is a summary of the Q-related data:"}]},{"_type":"appendixListCard","_key":"a8c","caption":{"children":[{"_type":"span","_key":"a7v","text":"Summary of Q-Related Data"}]},"item":"row","marker":"primarySmall","content":"body","contentTag":"span","items":[{"_key":"a7w","text":{"children":[{"_type":"span","_key":"a7x","text":"The frequency of occurrence of \"Q\" in Sura \"Q\" (No. 50) is 57, 19×3."}]}},{"_key":"a7y","text":{"children":[{"_type":"span","_key":"a7z","text":"The letter \"Q\" occurs in the other Q-initialed sura (No. 42) exactly the same number of times, 57."}]}},{"_key":"a80","text":{"children":[{"_type":"span","_key":"a81","text":"The total occurrence of the letter \"Q\" in the two Q-initialed suras is 114, which equals the number of suras in the Quran."}]}},{"_key":"a82","text":{"children":[{"_type":"span","_key":"a83","text":"\"The Quran\" is mentioned in the Quran 57 times."}]}},{"_key":"a84","text":{"children":[{"_type":"span","_key":"a85","text":"The description of the Quran as \"Majid\" (Glorious) is correlated with the frequency of occurrence of the letter \"Q\" in each of the Q-initialed suras. The word \"Majid\" has a gematrical value of 57."}]}},{"_key":"a86","text":{"children":[{"_type":"span","_key":"a87","text":"Sura 42 consists of 53 verses, and 42+53 = 95 = 19×5."}]}},{"_key":"a88","text":{"children":[{"_type":"span","_key":"a89","text":"Sura 50 consists of 45 verses, and 50+45 = 95 = 19×5."}]}},{"_key":"a8a","text":{"children":[{"_type":"span","_key":"a8b","text":"The number of Q's in all verses numbered \"19\" throughout the Quran is 76, 19×4."}]}}]},{"_type":"block","_key":"a8e","style":"normal","children":[{"_type":"span","_key":"a8d","text":"Glimpses of the Quran’s mathematical composition began to emerge. For example, it was observed that the people who disbelieved in Lot are mentioned in 50:13 and occur in the Quran 13 times — 7:80; 11:70, 74, 89; 21:74; 22:43; 26:160; 27:54, 56; 29:28; 38:13; 50:13; and 54:33. Consistently, they are referred to as “Qawm,” with the single exception of the Q-initialed Sura 50 where they are referred to as “Ikhwaan.” Obviously, if the regular, Q-containing word “Qawm” were used, the count of the letter “Q” in Sura 50 would have become 58, and this whole phenomenon would have disappeared. With the recognized absolute accuracy of mathematics, the alteration of a single letter destroys the system."}]},{"_type":"block","_key":"a8o","style":"normal","children":[{"_type":"span","_key":"a8f","text":"Another relevant example is the reference to Mecca in "},{"_type":"quranRef","_key":"a8g","reference":"3:96"},{"_type":"span","_key":"a8h","text":" as “Becca”! This strange spelling of the renowned city has puzzled Islamic scholars for many centuries. Although Mecca is mentioned in the Quran properly spelled in "},{"_type":"quranRef","_key":"a8i","reference":"48:24"},{"_type":"span","_key":"a8j","text":", the letter “M” is substituted with a “B” in "},{"_type":"quranRef","_key":"a8k","reference":"3:96"},{"_type":"span","_key":"a8l","text":". It turns out that Sura 3 is an M-initialed sura, and the count of the letter “M” would have deviated from the Quran’s code if “Mecca” was spelled correctly in "},{"_type":"quranRef","_key":"a8m","reference":"3:96"},{"_type":"span","_key":"a8n","text":"."}]},{"_type":"appendixDivider","_key":"a8p","title":{"children":[{"_type":"span","_key":"a8q","text":"NuN (Noon)"}]},"centered":true},{"_type":"block","_key":"a8s","style":"normal","children":[{"_type":"span","_key":"a8r","text":"This initial is unique; it occurs in one sura, 68, and the name of the letter is spelled out as three letters — Noon Wow Noon — in the original text, and is therefore counted as two N’s. The total count of this letter in the N-initialed sura is 133, 19×7."}]},{"_type":"block","_key":"a8u","style":"normal","children":[{"_type":"span","_key":"a8t","text":"The fact that “N” is the last Quranic Initial (see Table 1) brings out a number of special observations. For example, the number of verses from the first Quranic Initial (A.L.M. of 2:1) to the last initial (N. of 68:1) is 5263, or 19×277."}]},{"_type":"block","_key":"a8w","style":"normal","children":[{"_type":"span","_key":"a8v","text":"The word “God” (Allah) occurs 2641 (19×139) times between the first initial and the last initial. Since the total occurrence of the word “God” is 2698, it follows that its occurrence outside the initials “A.L.M.” of 2:1 on one side, and the initial “N” of 68:1 on the other side, is 57, 19×3. Tables 9 to 18 prove that the initial “NuN” must be spelled out to show two N’s."}]},{"_type":"appendixDivider","_key":"a8x","title":{"children":[{"_type":"span","_key":"a8y","text":"S (Saad)"}]},"centered":true},{"_type":"block","_key":"a92","style":"normal","children":[{"_type":"span","_key":"a8z","text":"This initial prefixes three suras, 7, 19, and 38, and the total occurrence of the letter “S” (Saad) in these three suras is 152, 19×8 (Table 2). It is noteworthy that in "},{"_type":"quranRef","_key":"a90","reference":"7:69"},{"_type":"span","_key":"a91","text":", the word “Bastatan” is written in some printings with a “Saad,” instead of “Seen.”"}]},{"_type":"appendixDataTable","_key":"a9i","caption":{"children":[{"_type":"span","_key":"a93","text":"Table 2: Frequency of Occurrence of the Letter \"S\" in the Saad-initialed Suras"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"a94","text":"Sura No."}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"a95","text":"Frequency of \"S\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"a96","style":"data","cells":[{"children":[{"_type":"span","_key":"a97","text":"7"}]},{"children":[{"_type":"span","_key":"a98","text":"97"}]}]},{"_key":"a99","style":"data","cells":[{"children":[{"_type":"span","_key":"a9a","text":"19"}]},{"children":[{"_type":"span","_key":"a9b","text":"26"}]}]},{"_key":"a9c","style":"data","cells":[{"children":[{"_type":"span","_key":"a9d","text":"38"}]},{"children":[{"_type":"span","_key":"a9e","text":"29"}]}]},{"_key":"a9f","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"a9g","text":"Total"}]},{"children":[{"_type":"span","_key":"a9h","text":"152 (19×8)"}]}]}]},{"_type":"block","_key":"a9k","style":"normal","children":[{"_type":"span","_key":"a9j","text":"This is an erroneous distortion that violates the Quran’s code. By looking at the oldest available copy of the Quran, the Tashkent Copy, it was found that the word “Bastatan” is correctly written with a “Seen” (see photocopy below)."}]},{"_type":"appendixCallout","_key":"a9l","tone":"primary","style":"highlight","content":[{"_type":"block","_key":"a9n","style":"eyebrowPrimarySm","children":[{"_type":"span","_key":"a9m","text":"Historical Note"}]},{"_type":"block","_key":"a9p","style":"base","children":[{"_type":"span","_key":"a9o","text":"The momentous discovery that “19” is the Quran’s common denominator became a reality in January 1974, coinciding with Zul-Hijjah 1393 A.H. The Quran was revealed in 13 B.H. (Before Hijrah). This makes the number of years from the revelation of the Quran to the revelation of its miracle 1393 + 13 = 1406 = 19×74. As noted above, the unveiling of the Miracle took place in January 1974. The correlation between 19×74 lunar years and 1974 solar years could not escape notice. This is especially uncanny in view of the fact that “19” is mentioned in Sura 74."}]}]},{"_type":"appendixDivider","_key":"a9q","title":{"children":[{"_type":"span","_key":"a9r","text":"Y.S. (Ya Seen)"}]},"centered":true},{"_type":"block","_key":"a9t","style":"normal","children":[{"_type":"span","_key":"a9s","text":"These two letters prefix Sura 36. The letter “Y” occurs in this sura 237 times, while the letter “S” (Seen) occurs 48 times. The total of both letters is 285, 19×15."}]},{"_type":"block","_key":"a9x","style":"normal","children":[{"_type":"span","_key":"a9u","text":"It is noteworthy that the letter “Y” is written in the Quran in two forms; one is obvious and the other is subtle. The subtle form of the letter may be confusing to those who are not thoroughly familiar with the Arabic language. A good example is the word “Araany” which is mentioned twice in "},{"_type":"quranRef","_key":"a9v","reference":"12:36"},{"_type":"span","_key":"a9w","text":". The letter “Y” is used twice in this word, the first “Y” is subtle and the second is obvious. Sura 36 does not contain a single “Y” of the subtle type. This is a remarkable phenomenon, and one that does not normally occur in a long sura like Sura 36. In my book QURAN: VISUAL PRESENTATION OF THE MIRACLE (Islamic Productions, 1982) every “Y” and “S” in Sura 36 is marked with a star."}]},{"_type":"appendixDivider","_key":"a9y","title":{"children":[{"_type":"span","_key":"a9z","text":"H.M. (Ha Mim)"}]},"centered":true},{"_type":"block","_key":"aa1","style":"normal","children":[{"_type":"span","_key":"aa0","text":"Seven suras are prefixed with the letters “H” and “M;” Suras 40 through 46. The total occurrence of these two letters in the seven H.M.-initialed suras is 2147, or 19×113. The detailed data are shown in Table 3."}]},{"_type":"block","_key":"aa3","style":"normal","children":[{"_type":"span","_key":"aa2","text":"Naturally, the alteration of a single letter “H” or “M” in any of the seven H.M.-initialed suras would have destroyed this intricate phenomenon."}]},{"_type":"appendixDataTable","_key":"abd","caption":{"children":[{"_type":"span","_key":"aa4","text":"Table 3: Occurrence of the Letters \"H\" and \"M\" in the Seven H.M.-Initialed Suras"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"aa5","text":"Sura No."}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"aa6","text":"Freq. of \"H\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"aa7","text":"Freq. of \"M\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"aa8","text":"H + M"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"aa9","style":"data","cells":[{"children":[{"_type":"span","_key":"aaa","text":"40"}]},{"children":[{"_type":"span","_key":"aab","text":"64"}]},{"children":[{"_type":"span","_key":"aac","text":"380"}]},{"children":[{"_type":"span","_key":"aad","text":"444"}]}]},{"_key":"aae","style":"data","cells":[{"children":[{"_type":"span","_key":"aaf","text":"41"}]},{"children":[{"_type":"span","_key":"aag","text":"48"}]},{"children":[{"_type":"span","_key":"aah","text":"276"}]},{"children":[{"_type":"span","_key":"aai","text":"324"}]}]},{"_key":"aaj","style":"data","cells":[{"children":[{"_type":"span","_key":"aak","text":"42"}]},{"children":[{"_type":"span","_key":"aal","text":"53"}]},{"children":[{"_type":"span","_key":"aam","text":"300"}]},{"children":[{"_type":"span","_key":"aan","text":"353"}]}]},{"_key":"aao","style":"data","cells":[{"children":[{"_type":"span","_key":"aap","text":"43"}]},{"children":[{"_type":"span","_key":"aaq","text":"44"}]},{"children":[{"_type":"span","_key":"aar","text":"324"}]},{"children":[{"_type":"span","_key":"aas","text":"368"}]}]},{"_key":"aat","style":"data","cells":[{"children":[{"_type":"span","_key":"aau","text":"44"}]},{"children":[{"_type":"span","_key":"aav","text":"16"}]},{"children":[{"_type":"span","_key":"aaw","text":"150"}]},{"children":[{"_type":"span","_key":"aax","text":"166"}]}]},{"_key":"aay","style":"data","cells":[{"children":[{"_type":"span","_key":"aaz","text":"45"}]},{"children":[{"_type":"span","_key":"ab0","text":"31"}]},{"children":[{"_type":"span","_key":"ab1","text":"200"}]},{"children":[{"_type":"span","_key":"ab2","text":"231"}]}]},{"_key":"ab3","style":"data","cells":[{"children":[{"_type":"span","_key":"ab4","text":"46"}]},{"children":[{"_type":"span","_key":"ab5","text":"36"}]},{"children":[{"_type":"span","_key":"ab6","text":"225"}]},{"children":[{"_type":"span","_key":"ab7","text":"261"}]}]},{"_key":"ab8","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"ab9","text":"Total"}]},{"children":[{"_type":"span","_key":"aba","text":"292"}]},{"children":[{"_type":"span","_key":"abb","text":"1855"}]},{"children":[{"_type":"span","_key":"abc","text":"2147 (19×113)"}]}]}]},{"_type":"appendixDivider","_key":"abe","title":{"children":[{"_type":"span","_key":"abf","text":"‘A.S.Q. (‘Ayn Seen Qaf)"}]},"centered":true},{"_type":"block","_key":"abh","style":"normal","children":[{"_type":"span","_key":"abg","text":"These initials constitute Verse 2 of Sura 42, and the total occurrence of these letters in this sura is 209, or 19×11. The letter “‘A” (‘Ayn) occurs 98 times, the letter “S” (Seen) occurs 54 times, and the letter “Q” (Qaf) occurs 57 times."}]},{"_type":"appendixDivider","_key":"abi","title":{"children":[{"_type":"span","_key":"abj","text":"A.L.M. (Alef Laam Mim)"}]},"centered":true},{"_type":"block","_key":"abl","style":"normal","children":[{"_type":"span","_key":"abk","text":"The letters “A,” “L,” and “M” are the most frequently used letters in the Arabic language, and in the same order as we see in the Quranic Initials — “A,” then “L,” then “M.” These letters prefix six suras — 2, 3, 29, 30, 31, and 32 — and the total occurrence of the three letters in each of the six suras is a multiple of 19: 9899 (19×521), 5662 (19×298), 1672 (19×88), 1254 (19×66), 817 (19×43), and 570 (19×30), respectively. Thus, the total occurrence of the three letters in the six suras is 19874 (19×1046), and the alteration of one of these letters destroys this phenomenon."}]},{"_type":"appendixDataTable","_key":"acy","caption":{"children":[{"_type":"span","_key":"abm","text":"Table 4: Occurrence of the Letters \"A,\" \"L,\" and \"M\" in the A.L.M.-Initialed Suras"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"abn","text":"Sura No."}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"abo","text":"Freq. of \"A\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"abp","text":"Freq. of \"L\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"abq","text":"Freq. of \"M\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"abr","text":"Total"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"abs","style":"data","cells":[{"children":[{"_type":"span","_key":"abt","text":"2"}]},{"children":[{"_type":"span","_key":"abu","text":"4502"}]},{"children":[{"_type":"span","_key":"abv","text":"3202"}]},{"children":[{"_type":"span","_key":"abw","text":"2195"}]},{"children":[{"_type":"span","_key":"abx","text":"9899 (19×521)"}]}]},{"_key":"aby","style":"data","cells":[{"children":[{"_type":"span","_key":"abz","text":"3"}]},{"children":[{"_type":"span","_key":"ac0","text":"2521"}]},{"children":[{"_type":"span","_key":"ac1","text":"1892"}]},{"children":[{"_type":"span","_key":"ac2","text":"1249"}]},{"children":[{"_type":"span","_key":"ac3","text":"5662 (19×298)"}]}]},{"_key":"ac4","style":"data","cells":[{"children":[{"_type":"span","_key":"ac5","text":"29"}]},{"children":[{"_type":"span","_key":"ac6","text":"774"}]},{"children":[{"_type":"span","_key":"ac7","text":"554"}]},{"children":[{"_type":"span","_key":"ac8","text":"344"}]},{"children":[{"_type":"span","_key":"ac9","text":"1672 (19×88)"}]}]},{"_key":"aca","style":"data","cells":[{"children":[{"_type":"span","_key":"acb","text":"30"}]},{"children":[{"_type":"span","_key":"acc","text":"544"}]},{"children":[{"_type":"span","_key":"acd","text":"393"}]},{"children":[{"_type":"span","_key":"ace","text":"317"}]},{"children":[{"_type":"span","_key":"acf","text":"1254 (19×66)"}]}]},{"_key":"acg","style":"data","cells":[{"children":[{"_type":"span","_key":"ach","text":"31"}]},{"children":[{"_type":"span","_key":"aci","text":"347"}]},{"children":[{"_type":"span","_key":"acj","text":"297"}]},{"children":[{"_type":"span","_key":"ack","text":"173"}]},{"children":[{"_type":"span","_key":"acl","text":"817 (19×43)"}]}]},{"_key":"acm","style":"data","cells":[{"children":[{"_type":"span","_key":"acn","text":"32"}]},{"children":[{"_type":"span","_key":"aco","text":"257"}]},{"children":[{"_type":"span","_key":"acp","text":"155"}]},{"children":[{"_type":"span","_key":"acq","text":"158"}]},{"children":[{"_type":"span","_key":"acr","text":"570 (19×30)"}]}]},{"_key":"acs","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"act","text":"Total"}]},{"children":[{"_type":"span","_key":"acu","text":"8945"}]},{"children":[{"_type":"span","_key":"acv","text":"6493"}]},{"children":[{"_type":"span","_key":"acw","text":"4436"}]},{"children":[{"_type":"span","_key":"acx","text":"19874 (19×1046)"}]}]}]},{"_type":"appendixDivider","_key":"acz","title":{"children":[{"_type":"span","_key":"ad0","text":"A.L.R. (Alef Laam Ra)"}]},"centered":true},{"_type":"block","_key":"ad2","style":"normal","children":[{"_type":"span","_key":"ad1","text":"These initials are found in Suras 10, 11, 12, 14, and 15. The total occurrences of these letters in these suras are 2489 (19×131), 2489 (19×131), 2375 (19×125), 1197 (19×63), and 912 (19×48), respectively (Table 5)."}]},{"_type":"appendixDataTable","_key":"ae9","caption":{"children":[{"_type":"span","_key":"ad3","text":"Table 5: Occurrence of the Letters \"A,\" \"L,\" and \"R\" in the A.L.R.-Initialed Suras"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"ad4","text":"Sura No."}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"ad5","text":"Freq. of \"A\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"ad6","text":"Freq. of \"L\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"ad7","text":"Freq. of \"R\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"ad8","text":"Total"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"ad9","style":"data","cells":[{"children":[{"_type":"span","_key":"ada","text":"10"}]},{"children":[{"_type":"span","_key":"adb","text":"1319"}]},{"children":[{"_type":"span","_key":"adc","text":"913"}]},{"children":[{"_type":"span","_key":"add","text":"257"}]},{"children":[{"_type":"span","_key":"ade","text":"2489 (19×131)"}]}]},{"_key":"adf","style":"data","cells":[{"children":[{"_type":"span","_key":"adg","text":"11"}]},{"children":[{"_type":"span","_key":"adh","text":"1370"}]},{"children":[{"_type":"span","_key":"adi","text":"794"}]},{"children":[{"_type":"span","_key":"adj","text":"325"}]},{"children":[{"_type":"span","_key":"adk","text":"2489 (19×131)"}]}]},{"_key":"adl","style":"data","cells":[{"children":[{"_type":"span","_key":"adm","text":"12"}]},{"children":[{"_type":"span","_key":"adn","text":"1306"}]},{"children":[{"_type":"span","_key":"ado","text":"812"}]},{"children":[{"_type":"span","_key":"adp","text":"257"}]},{"children":[{"_type":"span","_key":"adq","text":"2375 (19×125)"}]}]},{"_key":"adr","style":"data","cells":[{"children":[{"_type":"span","_key":"ads","text":"14"}]},{"children":[{"_type":"span","_key":"adt","text":"585"}]},{"children":[{"_type":"span","_key":"adu","text":"452"}]},{"children":[{"_type":"span","_key":"adv","text":"160"}]},{"children":[{"_type":"span","_key":"adw","text":"1197 (19×63)"}]}]},{"_key":"adx","style":"data","cells":[{"children":[{"_type":"span","_key":"ady","text":"15"}]},{"children":[{"_type":"span","_key":"adz","text":"493"}]},{"children":[{"_type":"span","_key":"ae0","text":"323"}]},{"children":[{"_type":"span","_key":"ae1","text":"96"}]},{"children":[{"_type":"span","_key":"ae2","text":"912 (19×48)"}]}]},{"_key":"ae3","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"ae4","text":"Total"}]},{"children":[{"_type":"span","_key":"ae5","text":"5073"}]},{"children":[{"_type":"span","_key":"ae6","text":"3294"}]},{"children":[{"_type":"span","_key":"ae7","text":"1095"}]},{"children":[{"_type":"span","_key":"ae8","text":"9462 (19×498)"}]}]}]},{"_type":"appendixDivider","_key":"aea","title":{"children":[{"_type":"span","_key":"aeb","text":"A.L.M.R. (Alef Laam Mim Ra)"}]},"centered":true},{"_type":"block","_key":"aed","style":"normal","children":[{"_type":"span","_key":"aec","text":"These initials prefix one sura, No. 13, and the total frequency of occurrence of the four letters is 1482, or 19×78. The letter “A” occurs 605 times, “L” occurs 480 times, “M” occurs 260 times, and “R” occurs 137 times."}]},{"_type":"appendixDivider","_key":"aee","title":{"children":[{"_type":"span","_key":"aef","text":"A.L.M.S. (Alef Laam Mim Saad)"}]},"centered":true},{"_type":"block","_key":"aeh","style":"normal","children":[{"_type":"span","_key":"aeg","text":"Only one sura is prefixed with these initials, Sura 7, and the letter “A” occurs in this sura 2529 times, “L” occurs 1530 times, “M” occurs 1164 times, and “S” (Saad) occurs 97 times. Thus, the total occurrence of the four letters in this sura is 2529 + 1530 + 1164 + 97 = 5320 = 19×280."}]},{"_type":"block","_key":"aej","style":"normal","children":[{"_type":"span","_key":"aei","text":"An important observation here is the interlocking relationship involving the letter “S” (Saad). This letter occurs also in Suras 19 and 38. While complementing its sister letters in Sura 7 to give a total that is divisible by 19, the frequency of this letter also complements its sister letters in Suras 19 and 38 to give a multiple of 19 (see Page 380)."}]},{"_type":"block","_key":"ael","style":"normal","children":[{"_type":"span","_key":"aek","text":"Additionally, the Quranic Initial “S” (Saad) interacts with the Quranic Initials “K.H.Y.‘A.” (Kaaf Ha Ya ‘Ayn) in Sura 19 to give another total that is also a multiple of 19 (see Page 383). This interlocking relationship — which is not unique to the initial “S” (Saad) — contributes to the intricacy of the Quran’s numerical code."}]},{"_type":"appendixDivider","_key":"aem","title":{"children":[{"_type":"span","_key":"aen","text":"K.H.Y.‘A.S. (Kaaf Ha Ya ‘Ayn Saad)"}]},"centered":true},{"_type":"block","_key":"aep","style":"normal","children":[{"_type":"span","_key":"aeo","text":"This is the longest set of initials, consisting of five letters, and it occurs in one sura, Sura 19. The letter “K” in Sura 19 occurs 137 times, “H” occurs 175 times, “Y” occurs 343 times, “‘A” occurs 117 times, and “S” (Saad) occurs 26 times. Thus, the total occurrence of the five letters is 137 + 175 + 343 + 117 + 26 = 798 = 19×42."}]},{"_type":"appendixDivider","_key":"aeq","title":{"children":[{"_type":"span","_key":"aer","text":"H., T.H. (Ta Ha), T.S. (Ta Seen) & T.S.M. (Ta Seen Mim)"}]},"centered":true},{"_type":"block","_key":"aet","style":"normal","children":[{"_type":"span","_key":"aes","text":"An intricate interlocking relationship links these overlapping Quranic Initials to produce a total that is also a multiple of 19. The initial “H.” is found in Suras 19 and 20. The initials “T.H.” prefix Sura 20. The initials “T.S.” are found in Sura 27, while the initials “T.S.M.” prefix its surrounding Suras 26 & 28."}]},{"_type":"block","_key":"aev","style":"normal","children":[{"_type":"span","_key":"aeu","text":"It should be noted at this time that the longer, more complex, interlocking and overlapping initials are found in the suras where uncommonly powerful miracles are narrated. For example, the virgin birth of Jesus is given in Sura 19, which is prefixed with the longest set of initials, K.H.Y.‘A.S."}]},{"_type":"block","_key":"aex","style":"normal","children":[{"_type":"span","_key":"aew","text":"The interlocking initials “H.,” “T.H.,” “T.S.,” and “T.S.M.” prefix suras describing the miracles of Moses, Jesus, and the uncommon occurrences surrounding Solomon and his jinns. God thus provides stronger evidence to support stronger miracles. The frequencies of occurrence of these initials are presented in Table 6."}]},{"_type":"appendixDataTable","_key":"ag4","caption":{"children":[{"_type":"span","_key":"aey","text":"Table 6: Occurrence of the Quranic Initials \"H.,\" \"T.H.,\" \"T.S.,\" and \"T.S.M.\" in Their Suras"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"aez","text":"Sura"}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"af0","text":"Freq. of \"H\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"af1","text":"Freq. of \"T\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"af2","text":"Freq. of \"S\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"af3","text":"Freq. of \"M\""}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"af4","style":"data","cells":[{"children":[{"_type":"span","_key":"af5","text":"19"}]},{"children":[{"_type":"span","_key":"af6","text":"175"}]},{"children":[{"_type":"span","_key":"af7","text":"—"}]},{"children":[{"_type":"span","_key":"af8","text":"—"}]},{"children":[{"_type":"span","_key":"af9","text":"—"}]}]},{"_key":"afa","style":"data","cells":[{"children":[{"_type":"span","_key":"afb","text":"20"}]},{"children":[{"_type":"span","_key":"afc","text":"251"}]},{"children":[{"_type":"span","_key":"afd","text":"28"}]},{"children":[{"_type":"span","_key":"afe","text":"—"}]},{"children":[{"_type":"span","_key":"aff","text":"—"}]}]},{"_key":"afg","style":"data","cells":[{"children":[{"_type":"span","_key":"afh","text":"26"}]},{"children":[{"_type":"span","_key":"afi","text":"—"}]},{"children":[{"_type":"span","_key":"afj","text":"33"}]},{"children":[{"_type":"span","_key":"afk","text":"94"}]},{"children":[{"_type":"span","_key":"afl","text":"484"}]}]},{"_key":"afm","style":"data","cells":[{"children":[{"_type":"span","_key":"afn","text":"27"}]},{"children":[{"_type":"span","_key":"afo","text":"—"}]},{"children":[{"_type":"span","_key":"afp","text":"27"}]},{"children":[{"_type":"span","_key":"afq","text":"94"}]},{"children":[{"_type":"span","_key":"afr","text":"—"}]}]},{"_key":"afs","style":"data","cells":[{"children":[{"_type":"span","_key":"aft","text":"28"}]},{"children":[{"_type":"span","_key":"afu","text":"—"}]},{"children":[{"_type":"span","_key":"afv","text":"19"}]},{"children":[{"_type":"span","_key":"afw","text":"102"}]},{"children":[{"_type":"span","_key":"afx","text":"460"}]}]},{"_key":"afy","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"afz","text":"Total"}]},{"children":[{"_type":"span","_key":"ag0","text":"426"}]},{"children":[{"_type":"span","_key":"ag1","text":"107"}]},{"children":[{"_type":"span","_key":"ag2","text":"290"}]},{"children":[{"_type":"span","_key":"ag3","text":"944"}]}]}]},{"_type":"appendixCallout","_key":"ag5","tone":"primary","style":"highlightCentered","content":[{"_type":"block","_key":"ag7","style":"primary","children":[{"_type":"span","_key":"ag6","text":"426 + 107 + 290 + 944 = 1767 = 19×93"}]}]},{"_type":"appendixDivider","_key":"ag8","title":{"children":[{"_type":"span","_key":"ag9","text":"What Is a “Gematrical Value”?"}]},"centered":true},{"_type":"block","_key":"agb","style":"normal","children":[{"_type":"span","_key":"aga","text":"When the Quran was revealed, 14 centuries ago, the numbers known today did not exist. A universal system was used where the letters of the Arabic, Hebrew, Aramaic, and Greek alphabets were used as numerals. The number assigned to each letter is its “Gematrical Value.” The numerical values of the Arabic alphabet are shown in Table 7."}]},{"_type":"appendixDataTable","_key":"aih","caption":{"children":[{"_type":"span","_key":"agc","text":"Table 7: Gematrical Values of the Arabic Alphabet"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"agd","text":"Letter"}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"age","text":"Value"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"agf","text":"Letter"}]},"headerSty