bs","text":"Total"}]},{"children":[{"_type":"span","_key":"a1bt","text":"1798 + 634"}]},{"children":[{"_type":"span","_key":"a1bu","text":"57 (19×3)"}]}]}]},{"_type":"appendixCallout","_key":"a1bw","tone":"primary","style":"highlightCentered","content":[{"_type":"block","_key":"a1by","style":"primary","children":[{"_type":"span","_key":"a1bx","text":"Sum of numbers of the suras & verses = 1798 + 634 = 2432 = 19×128"}]},{"_type":"block","_key":"a1c0","style":"primary","children":[{"_type":"span","_key":"a1bz","text":"Total occurrence of the word “God” outside the initialed section = 57 (19×3)"}]}]},{"_type":"appendixDataTable","_key":"a1dh","caption":{"children":[{"_type":"span","_key":"a1c1","text":"Table 19: All Suras in Which the Word \"God\" (Allah) Is Mentioned"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"a1c2","text":"No."}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"a1c3","text":"Sura No."}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"a1c4","text":"First Verse"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"a1c5","text":"Last Verse"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"a1c6","text":"# Verses From First to Last"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"a1c7","style":"data","cells":[{"children":[{"_type":"span","_key":"a1c8","text":"1."}]},{"children":[{"_type":"span","_key":"a1c9","text":"1"}]},{"children":[{"_type":"span","_key":"a1ca","text":"1"}]},{"children":[{"_type":"span","_key":"a1cb","text":"2"}]},{"children":[{"_type":"span","_key":"a1cc","text":"2"}]}]},{"_key":"a1cd","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ce","text":"2."}]},{"children":[{"_type":"span","_key":"a1cf","text":"2"}]},{"children":[{"_type":"span","_key":"a1cg","text":"7"}]},{"children":[{"_type":"span","_key":"a1ch","text":"286"}]},{"children":[{"_type":"span","_key":"a1ci","text":"280"}]}]},{"_key":"a1cj","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ck","text":"3."}]},{"children":[{"_type":"span","_key":"a1cl","text":"3"}]},{"children":[{"_type":"span","_key":"a1cm","text":"2"}]},{"children":[{"_type":"span","_key":"a1cn","text":"200"}]},{"children":[{"_type":"span","_key":"a1co","text":"199"}]}]},{"_key":"a1cp","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"a1cq","text":"—"}]},{"children":[{"_type":"span","_key":"a1cr","text":"—"}]},{"children":[{"_type":"span","_key":"a1cs","text":"—"}]},{"children":[{"_type":"span","_key":"a1ct","text":"—"}]},{"children":[{"_type":"span","_key":"a1cu","text":"—"}]}]},{"_key":"a1cv","style":"data","cells":[{"children":[{"_type":"span","_key":"a1cw","text":"83."}]},{"children":[{"_type":"span","_key":"a1cx","text":"104"}]},{"children":[{"_type":"span","_key":"a1cy","text":"6"}]},{"children":[{"_type":"span","_key":"a1cz","text":"—"}]},{"children":[{"_type":"span","_key":"a1d0","text":"1"}]}]},{"_key":"a1d1","style":"data","cells":[{"children":[{"_type":"span","_key":"a1d2","text":"84."}]},{"children":[{"_type":"span","_key":"a1d3","text":"110"}]},{"children":[{"_type":"span","_key":"a1d4","text":"1"}]},{"children":[{"_type":"span","_key":"a1d5","text":"2"}]},{"children":[{"_type":"span","_key":"a1d6","text":"2"}]}]},{"_key":"a1d7","style":"data","cells":[{"children":[{"_type":"span","_key":"a1d8","text":"85."}]},{"children":[{"_type":"span","_key":"a1d9","text":"112"}]},{"children":[{"_type":"span","_key":"a1da","text":"1"}]},{"children":[{"_type":"span","_key":"a1db","text":"2"}]},{"children":[{"_type":"span","_key":"a1dc","text":"2"}]}]},{"_key":"a1dd","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"a1de","text":"Total"}]},{"children":[{"_type":"span","_key":"a1df","text":"3910"}]},{"children":[]},{"children":[]},{"children":[{"_type":"span","_key":"a1dg","text":"4260"}]}]}]},{"_type":"appendixCallout","_key":"a1di","tone":"primary","style":"highlightCentered","content":[{"_type":"block","_key":"a1dk","style":"primary","children":[{"_type":"span","_key":"a1dj","text":"3910 + 4260 = 8170 = 19×430"}]},{"_type":"block","_key":"a1dm","style":"note","children":[{"_type":"span","_key":"a1dl","text":"These mathematical properties cover all occurrences of the word “God.”"}]}]},{"_type":"block","_key":"a1do","style":"normal","children":[{"_type":"span","_key":"a1dn","text":"[7] The Quran’s dominant message is that there is only “One God.” The word “One,” in Arabic “Wahed” occurs in the Quran 25 times. Six of these occurrences refer to other than God (one kind of food, one door, etc.). The other 19 occurrences refer to God. These data are found in the classic reference INDEX TO THE WORDS OF QURAN."}]},{"_type":"block","_key":"a1dq","style":"normal","children":[{"_type":"span","_key":"a1dp","text":"The crucial importance of the word “ONE” as the Quran’s basic message is manifested in the fact that the Quran’s common denominator, 19, happens to be the gematrical value of the word “ONE” (Wahed): W(6) + A(1) + H(8) + D(4) = 19."}]},{"_type":"appendixDivider","_key":"a1dr","title":{"children":[{"_type":"span","_key":"a1ds","text":"Why 19!"}]},"centered":true},{"_type":"appendixSection","_key":"a1e2","style":"prose","tag":"section","content":[{"_type":"block","_key":"a1du","style":"normal","children":[{"_type":"span","_key":"a1dt","text":"As pointed out later in this Appendix, all God’s scriptures, not only the Quran, were mathematically coded with the number “19.” Even the universe at large bears this divine mark. The number 19 can be looked upon as the Almighty Creator’s signature on everything He created (see Appendix 38). The number “19” possesses unique mathematical properties beyond the scope of this Appendix. For example:"}]},{"_type":"appendixBadgeList","_key":"a1e1","ordered":true,"style":"decimal","item":"none","content":"none","contentTag":"none","items":[{"_key":"a1dv","text":{"children":[{"_type":"span","_key":"a1dw","text":"It is a prime number."}]}},{"_key":"a1dx","text":{"children":[{"_type":"span","_key":"a1dy","text":"It encompasses the first numeral (1) and the last numeral (9), as if to proclaim God’s attribute in 57:3 as the “Alpha and the Omega.”"}]}},{"_key":"a1dz","text":{"children":[{"_type":"span","_key":"a1e0","text":"It looks the same in all languages of the world. Both components, 1 and 9, are the only numerals that look the same in all languages."}]}}]}]},{"_type":"appendixCallout","_key":"a1e3","tone":"muted","style":"attributionStacked","content":[{"_type":"block","_key":"a1e5","style":"centerRelaxed","children":[{"_type":"span","_key":"a1e4","text":"The Lord our God is ONE!\nTherefore, you shall worship the Lord your God with all your heart, with all your soul, with all your mind, and with all your strength."}]},{"_type":"block","_key":"a1e7","style":"centerXs","children":[{"_type":"span","_key":"a1e6","text":"[Deuteronomy 6:4-5] [Mark 12:29] [Quran 2:163, 17:22-23]"}]}],"reveal":false},{"_type":"appendixSection","_key":"a1ed","style":"prose","tag":"section","content":[{"_type":"appendixBadgeList","_key":"a1ea","ordered":true,"style":"decimal","item":"none","content":"none","contentTag":"none","items":[{"_key":"a1e8","text":{"children":[{"_type":"span","_key":"a1e9","text":"It possesses many peculiar mathematical properties. For example, 19 is the sum of the first powers of 9 and 10, and the difference between the second powers of 9 and 10."}]}}]},{"_type":"block","_key":"a1ec","style":"normal","children":[{"_type":"span","_key":"a1eb","text":"We now understand that the universal coding of God’s creations with the number 19 rests in the fact that it is the gematrical value of the word “ONE” in all the scriptural languages — Aramaic, Hebrew, and Arabic."}]}]},{"_type":"appendixDataTable","_key":"a1f1","caption":{"children":[{"_type":"span","_key":"a1ee","text":"Table 20: Why 19!"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"a1ef","text":"Letter (Hebrew)"}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"a1eg","text":"Letter (Arabic)"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"},{"header":{"children":[{"_type":"span","_key":"a1eh","text":"Value"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"a1ei","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ej","text":"V"}]},{"children":[{"_type":"span","_key":"a1ek","text":"W"}]},{"children":[{"_type":"span","_key":"a1el","text":"6"}]}]},{"_key":"a1em","style":"data","cells":[{"children":[{"_type":"span","_key":"a1en","text":"A"}]},{"children":[{"_type":"span","_key":"a1eo","text":"A"}]},{"children":[{"_type":"span","_key":"a1ep","text":"1"}]}]},{"_key":"a1eq","style":"data","cells":[{"children":[{"_type":"span","_key":"a1er","text":"H"}]},{"children":[{"_type":"span","_key":"a1es","text":"H"}]},{"children":[{"_type":"span","_key":"a1et","text":"8"}]}]},{"_key":"a1eu","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ev","text":"D"}]},{"children":[{"_type":"span","_key":"a1ew","text":"D"}]},{"children":[{"_type":"span","_key":"a1ex","text":"4"}]}]},{"_key":"a1ey","style":"dataEmphasised","cells":[{"children":[{"_type":"span","_key":"a1ez","text":"Total"}]},{"children":[]},{"children":[{"_type":"span","_key":"a1f0","text":"19"}]}]}]},{"_type":"block","_key":"a1f3","style":"normal","children":[{"_type":"span","_key":"a1f2","text":"The number 19, therefore, proclaims the First Commandment in all the scriptures: that there is only ONE God."}]},{"_type":"block","_key":"a1f5","style":"normal","children":[{"_type":"span","_key":"a1f4","text":"As shown in Table 7, the Aramaic, Hebrew, and Arabic alphabets used to double as numerals in accordance with a universally established system. The Hebrew word for “ONE” is “VAHD” (pronounced V-AHAD). In Arabic, the word for “ONE” is “WAHD” (pronounced WAAHED). See Table 20."}]},{"_type":"appendixDivider","_key":"a1f6","title":{"children":[{"_type":"span","_key":"a1f7","text":"The Word “Quran”"}]},"centered":true},{"_type":"block","_key":"a1f9","style":"normal","children":[{"_type":"span","_key":"a1f8","text":"The word “Quran” occurs in the Quran 58 times, with one of them, in 10:15, referring to “another Quran.” This particular occurrence, therefore, must be excluded. Thus, the frequency of occurrence of “this Quran” in the Quran is 57, or 19×3."}]},{"_type":"appendixDataTable","_key":"a1ky","caption":{"children":[{"_type":"span","_key":"a1fa","text":"Table 21: Suras and Verses Where \"Quran\" Occurs"}]},"table":"plain","columns":[{"header":{"children":[{"_type":"span","_key":"a1fb","text":"Sura"}]},"headerStyle":"leftSemibold","cellStyle":"monoPrimaryMediumTop"},{"header":{"children":[{"_type":"span","_key":"a1fc","text":"Verse"}]},"headerStyle":"leftSemibold","cellStyle":"plainTop"}],"rows":[{"_key":"a1fd","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fe","text":"2"}]},{"children":[{"_type":"span","_key":"a1ff","text":"185"}]}]},{"_key":"a1fg","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fh","text":"4"}]},{"children":[{"_type":"span","_key":"a1fi","text":"82"}]}]},{"_key":"a1fj","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fk","text":"5"}]},{"children":[{"_type":"span","_key":"a1fl","text":"101"}]}]},{"_key":"a1fm","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fn","text":"6"}]},{"children":[{"_type":"span","_key":"a1fo","text":"19"}]}]},{"_key":"a1fp","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fq","text":"7"}]},{"children":[{"_type":"span","_key":"a1fr","text":"204"}]}]},{"_key":"a1fs","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ft","text":"9"}]},{"children":[{"_type":"span","_key":"a1fu","text":"111"}]}]