 14 illustrates this remarkable phenomenon."}]},{"_type":"appendixDataTable","_key":"aqn","caption":{"children":[{"_type":"span","_key":"ap9","text":"Table 14: Same data as in Table 12, but only for the odd-numbered suras"}]},"table":"collapse","columns":[{"header":{"children":[{"_type":"span","_key":"apa","text":"Sura No."}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapPrimary"},{"header":{"children":[{"_type":"span","_key":"apb","text":"No. of Verses"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"apc","text":"Σ Digits (Sura)"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"apd","text":"Σ Digits (Verses)"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"ape","text":"Total"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"}],"rows":[{"_key":"apf","style":"data","cells":[{"children":[{"_type":"span","_key":"apg","text":"1"}]},{"children":[{"_type":"span","_key":"aph","text":"7"}]},{"children":[{"_type":"span","_key":"api","text":"1"}]},{"children":[{"_type":"span","_key":"apj","text":"7"}]},{"children":[{"_type":"span","_key":"apk","text":"8"}]}]},{"_key":"apl","style":"data","cells":[{"children":[{"_type":"span","_key":"apm","text":"3"}]},{"children":[{"_type":"span","_key":"apn","text":"200"}]},{"children":[{"_type":"span","_key":"apo","text":"3"}]},{"children":[{"_type":"span","_key":"app","text":"2"}]},{"children":[{"_type":"span","_key":"apq","text":"5"}]}]},{"_key":"apr","style":"data","cells":[{"children":[{"_type":"span","_key":"aps","text":"–"}]},{"children":[{"_type":"span","_key":"apt","text":"–"}]},{"children":[{"_type":"span","_key":"apu","text":"–"}]},{"children":[{"_type":"span","_key":"apv","text":"–"}]},{"children":[{"_type":"span","_key":"apw","text":"–"}]}]},{"_key":"apx","style":"data","cells":[{"children":[{"_type":"span","_key"