text":"8385"}]},{"children":[{"_type":"span","_key":"a1dg","text":"8523"}]}]},{"_key":"a1dh","style":"data","cells":[{"children":[{"_type":"span","_key":"a1di","text":"25"}]},{"children":[{"_type":"span","_key":"a1dj","text":"77"}]},{"children":[{"_type":"span","_key":"a1dk","text":"3003"}]},{"children":[{"_type":"span","_key":"a1dl","text":"3105"}]}]},{"_key":"a1dm","style":"data","cells":[{"children":[{"_type":"span","_key":"a1dn","text":"27"}]},{"children":[{"_type":"span","_key":"a1do","text":"93"}]},{"children":[{"_type":"span","_key":"a1dp","text":"4371"}]},{"children":[{"_type":"span","_key":"a1dq","text":"4491"}]}]},{"_key":"a1dr","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ds","text":"37"}]},{"children":[{"_type":"span","_key":"a1dt","text":"182"}]},{"children":[{"_type":"span","_key":"a1du","text":"16653"}]},{"children":[{"_type":"span","_key":"a1dv","text":"16872"}]}]},{"_key":"a1dw","style":"data","cells":[{"children":[{"_type":"span","_key":"a1dx","text":"68"}]},{"children":[{"_type":"span","_key":"a1dy","text":"52"}]},{"children":[{"_type":"span","_key":"a1dz","text":"1378"}]},{"children":[{"_type":"span","_key":"a1e0","text":"1498"}]}]},{"_key":"a1e1","style":"data","cells":[{"children":[{"_type":"span","_key":"a1e2","text":"94"}]},{"children":[{"_type":"span","_key":"a1e3","text":"8"}]},{"children":[{"_type":"span","_key":"a1e4","text":"36"}]},{"children":[{"_type":"span","_key":"a1e5","text":"138"}]}]},{"_key":"a1e6","style":"data","cells":[{"children":[{"_type":"span","_key":"a1e7","text":"97"}]},{"children":[{"_type":"span","_key":"a1e8","text":"5"}]},{"children":[{"_type":"span","_key":"a1e9","text":"15"}]},{"children":[{"_type":"span","_key":"a1ea","text":"117"}]}]},{"_key":"a1eb","style":"totalsPrimary","cells":[{"children":[{"_type":"span","_key":"a1ec","text":"357"}]},{"children":[{"_type":"span","_key":"a1ed","text":"546"}]},{"children":[{"_type":"span","_key":"a1ee","text":"33841"}]},{"children":[{"_type":"span","_key":"a1ef","text":"34744"}]}],"cellStyles":["monoPrimaryNowrap","monoPrimaryNowrap","monoPrimaryNowrap","monoPrimaryNowrap"]}],"note":{"style":"band","content":[{"_type":"block","_key":"a1d6","style":"normal","bare":true,"children":[{"_type":"span","_key":"a1d7","text":"(Not divisible by 19)"}]}]}},{"_type":"block","_key":"a1ei","style":"normal","children":[{"_type":"span","_key":"a1eh","text":"Now, let us use the correct number of verses for Sura 9, 127, and repeat the same calculations as in Table 35. This causes the grand total to become 34485, or 19×1815. See Table 36."}]},{"_type":"appendixDataTable","_key":"a1fs","caption":{"children":[{"_type":"span","_key":"a1ej","text":"Table 36: Calculations of Table 35, after correcting the verses in Sura 9"}]},"table":"collapse","columns":[{"header":{"children":[{"_type":"span","_key":"a1ek","text":"Sura No."}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapPrimary"},{"header":{"children":[{"_type":"span","_key":"a1el","text":"No. of Verses"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"a1em","text":"Sum of Verse #s"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"a1en","text":"Total"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"}],"rows":[{"_key":"a1eo","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ep","text":"9"}]},{"children":[{"_type":"span","_key":"a1eq","text":"127"}]},{"children":[{"_type":"span","_key":"a1er","text":"8128"}]},{"children":[{"_type":"span","_key":"a1es","text":"8264"}]}]},{"_key":"a1et","style":"data","cells":[{"children":[{"_type":"span","_key":"a1eu","text":"25"}]},{"children":[{"_type":"span","_key":"a1ev","text":"77"}]},{"children":[{"_type":"span","_key":"a1ew","text":"3003"}]},{"children":[{"_type":"span","_key":"a1ex","text":"3105"}]}]},{"_key":"a1ey","style":"data","cells":[{"children":[{"_type":"span","_key":"a1ez","text":"27"}]},{"children":[{"_type":"span","_key":"a1f0","text":"93"}]},{"children":[{"_type":"span","_key":"a1f1","text":"4371"}]},{"children":[{"_type":"span","_key":"a1f2","text":"4491"}]}]},{"_key":"a1f3","style":"data","cells":[{"children":[{"_type":"span","_key":"a1f4","text":"37"}]},{"children":[{"_type":"span","_key":"a1f5","text":"182"}]},{"children":[{"_type":"span","_key":"a1f6","text":"16653"}]},{"children":[{"_type":"span","_key":"a1f7","text":"16872"}]}]},{"_key":"a1f8","style":"data","cells":[{"children":[{"_type":"span","_key":"a1f9","text":"68"}]},{"children":[{"_type":"span","_key":"a1fa","text":"52"}]},{"children":[{"_type":"span","_key":"a1fb","text":"1378"}]},{"children":[{"_type":"span","_key":"a1fc","text":"1498"}]}]},{"_key":"a1fd","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fe","text":"94"}]},{"children":[{"_type":"span","_key":"a1ff","text":"8"}]},{"children":[{"_type":"span","_key":"a1fg","text":"36"}]},{"children":[{"_type":"span","_key":"a1fh","text":"138"}]}]},{"_key":"a1fi","style":"data","cells":[{"children":[{"_type":"span","_key":"a1fj","text":"97"}]},{"children":[{"_type":"span","_key":"a1fk","text":"5"}]},{"children":[{"_type":"span","_key":"a1fl","text":"15"}]},{"children":[{"_type":"span","_key":"a1fm","text":"117"}]}]},{"_key":"a1fn","style":"totalsPrimary","cells":[{"children":[{"_type":"span","_key":"a1fo","text":"357"}]},{"children":[{"_type":"span","_key":"a1fp","text":"544"}]},{"children":[{"_type":"span","_key":"a1fq","text":"33584"}]},{"children":[{"_type":"span","_key":"a1fr","text":"34485 = 19×1815"}]}],"cellStyles":["monoPrimaryNowrap","monoPrimaryNowrap","monoPrimaryNowrap","monoPrimaryNowrap"]}]}]},{"_type":"appendixEvidence","_key":"a1ft","n":56,"marker":"primary","body":"evidenceBody","content":[{"_type":"block","_key":"a1fw","style":"normal","children":[{"_type":"span","_key":"a1fv","text":"For the last time, let us assume that Sura 9 consists of 129 verses. We have here a sura that (1) is an odd numbered sura, (2) its number is divisible by 3, (3) the number of verses, 129, is also divisible by 3, and (4) the number of verses ends with the digit “9.” There is only one sura that possesses these qualities: Sura 15 is divisible by 3, its number of verses is 99, which is divisible by 3 and ends with the digit “9.” If Sura 9 consisted of 129, and we added the sura and verse numbers for these two suras, we would end up with the following results: 9 + 129 + 15 + 99 = 252 — not a multiple of 19."}]},{"_type":"block","_key":"a1fy","style":"normal","children":[{"_type":"span","_key":"a1fx","text":"If we throw away the false number 129, we have one sura in the Quran whose number is odd, and its number of verses is divisible by 3 and ends with the digit 9 — Sura 15. Now we have the following result:"}]},{"_type":"appendixStatement","_key":"a1fz","text":{"children":[{"_type":"span","_key":"a1g0","text":"15 + 99 = 114 = 19×6."}]}}]},{"_type":"appendixEvidence","_key":"a1g1","n":57,"marker":"primary","body":"evidenceBody","content":[{"_type":"block","_key":"a1g4","style":"normal","children":[{"_type":"span","_key":"a1g3","text":"For some time now, we have been dealing with numbers. Let us now look at specific words and letters that occur in the false injections 9:128-129. The last statement in 9:127 describes the disbelievers as “LAA YAFQAHOON” (they do not comprehend). Thus, the last letter in Sura 9 is “N” (Noon). According to the falsifiers, the last verse is 129, and the last letter is “M” (Meem), since the last false word is “AZEEM.” Now let us look at the first letter and the last letter of every sura from the beginning of the Quran to Sura 9, and calculate their gematrical (numerical) values. Table 37 shows that the last true letter in Sura 9 must be “N,” not “M.”"}]},{"_type":"appendixDataTable","_key":"a1hr","caption":{"children":[{"_type":"span","_key":"a1g5","text":"Table 37: Gematrical value of the first and last letters of every sura from the beginning of the Quran to Sura 9"}]},"table":"collapse","columns":[{"header":{"children":[{"_type":"span","_key":"a1g6","text":"Sura No."}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapPrimary"},{"header":{"children":[{"_type":"span","_key":"a1g7","text":"First Letter"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"a1g8","text":"Last Letter"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"},{"header":{"children":[{"_type":"span","_key":"a1g9","text":"Total"}]},"headerStyle":"leftNowrap","cellStyle":"tightMonoNowrapFaded"}],"rows":[{"_key":"a1ga","style":"data","cells":[{"children":[{"_type":"span","_key":"a1gb","text":"1"}]},{"children":[{"_type":"span","_key":"a1gc","text":"B = 2"}]},{"children":[{"_type":"span","_key":"a1gd","text":"N = 50"}]},{"children":[{"_type":"span","_key":"a1ge","text":"52"}]}]},{"_key":"a1gf","style":"data","cells":[{"children":[{"_type":"span","_key":"a1gg","text":"2"}]},{"children":[{"_type":"span","_key":"a1gh","text":"A = 1"}]},{"children":[{"_type":"span","_key":"a1gi","text":"N = 50"}]},{"children":[{"_type":"span","_key":"a1gj","text":"51"}]}]},{"_key":"a1gk","style":"data","cells":[{"children":[{"_type":"span","_key":"a1gl","text":"3"}]},{"children":[{"_type":"span","_key":"a1gm","text":"A = 1"}]},{"children":[{"_type":"span","_key":"a1gn","text":"N = 50"}]},{"children":[{"_type":"span","_key":"a1go","text":"51"}]}]},{"_key":"a1gp","style":"data","cells":[{"children":[{"_type":"span","_key":"a1gq","text":"4"}]},{"children":[{"_type":"span","_key":"a1gr","text":"Y = 10"}]},{"children":[{"_type":"span","_key":"a1gs","text":"M = 40"}]},{"children":[{"_type":"span","_key":"a1gt","text":"50"}]}]},{"_key":"a1gu","style":"data","cells":[{"children":[{"_type":"span","_key":"a1gv","text":"5"}]},{"children":[{"_type":"span","_key":"a1gw","text":"Y = 10"}]},{"children":[{"_type":"span","_key":"a1gx","text":"R = 200"}]},{"children":[{"_type":"span","_key":"a1gy","text":