,{"content":{"children":[{"_type":"span","_key":"a1z","text":"253"}]}},{"content":{"children":[{"_type":"span","_key":"a20","text":"360"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a21","text":"86"}]}},{"content":{"children":[{"_type":"span","_key":"a22","text":"17"}]}},{"content":{"children":[{"_type":"span","_key":"a23","text":"153"}]}},{"content":{"children":[{"_type":"span","_key":"a24","text":"256"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a25","text":"87"}]}},{"content":{"children":[{"_type":"span","_key":"a26","text":"19"}]}},{"content":{"children":[{"_type":"span","_key":"a27","text":"190"}]}},{"content":{"children":[{"_type":"span","_key":"a28","text":"296"}]}}]},{"variant":"total","cells":[{"content":{"children":[{"_type":"span","_key":"a29","text":"3827"}]}},{"content":{"children":[{"_type":"span","_key":"a2a","text":"5835"}]}},{"content":{"children":[{"_type":"span","_key":"a2b","text":"323598"}]}},{"content":{"children":[{"_type":"span","_key":"a2c","text":"333260 (19×17540)"}]}}]}]},{"_type":"block","_key":"a2l","style":"normal","children":[{"_type":"span","_key":"a2e","text":"[4] As pointed out in "},{"_type":"span","_key":"a2g","text":"Appendix 2","marks":["a2f"]},{"_type":"span","_key":"a2h","text":", the name of God's Messenger of the Covenant is introduced to the computer age through mathematical coding. If the name was specified in the Quran, as is the case with past messengers, millions of people would have named their children “Rashad Khalifa.” Thus, the root word “Rashada” is mentioned in the Quran 19 times ("},{"_type":"span","_key":"a2j","text":"Appendix 2","marks":["a2i"]},{"_type":"span","_key":"a2k","text":")."}],"markDefs":[{"_key":"a2f","_type":"link","href":"/appendices/2"},{"_key":"a2i","_type":"link","href":"/appendices/2"}]},{"_type":"block","_key":"a2n","style":"normal","children":[{"_type":"span","_key":"a2m","text":"[5] “Abraham” is mentioned in 25 suras,