"span","_key":"aeh","text":"1"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"aei","text":"51"}]}},{"content":{"children":[{"_type":"span","_key":"aej","text":"24"}]}},{"content":{"children":[{"_type":"span","_key":"aek","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"ael","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"aem","text":"1"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"aen","text":"53"}]}},{"content":{"children":[{"_type":"span","_key":"aeo","text":"37"}]}},{"content":{"children":[{"_type":"span","_key":"aep","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"aeq","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"aer","text":"1"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"aes","text":"57"}]}},{"content":{"children":[{"_type":"span","_key":"aet","text":"26"}]}},{"content":{"children":[{"_type":"span","_key":"aeu","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"aev","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"aew","text":"1"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"aex","text":"60"}]}},{"content":{"children":[{"_type":"span","_key":"aey","text":"4"}]}},{"content":{"children":[{"_type":"span","_key":"aez","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"af0","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"af1","text":"1"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"af2","text":"72"}]}},{"content":{"children":[{"_type":"span","_key":"af3","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"af4","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"af5","text":"2, 10, 14, 21"}]}},{"content":{"children":[{"_type":"span","_key":"af6","text":"4"}]}}]},{"variant":"data","alignTop":true,"cells":[{"content":{"children":[{"_type":"span","_key":"af7","text":"87"}]}},{"content":{"children":[{"_type":"span","_key":"af8","text":"19"}]}},{"content":{"children":[{"_type":"span","_key":"af9","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"afa","text":"-"}]}},{"content":{"children":[{"_type":"span","_key":"afb","text":"1"}]}}]},{"variant":"total","cells":[{"content":{"children":[{"_type":"span","_key":"afc","text":"991"}]}},{"content":{"children":[{"_type":"span","_key":"afd","text":"5068"}]}},{"content":{"children":[{"_type":"span","_key":"afe","text":"215"}]}},{"content":{"children":[{"_type":"span","_key":"aff","text":"1145"}]}},{"content":{"children":[{"_type":"span","_key":"afg","text":"86"}]}}]}],"notes":[{"children":[{"_type":"span","_key":"afh","text":"991+5068+215+1145+86 = 7505 = 19×395."}]}]},{"_type":"block","_key":"afk","style":"normal","children":[{"_type":"span","_key":"afj","text":"Thus, it is mathematically coded into the Quran that Abraham, Muhammad, and Rashad are the three messengers of Islam (Submission)."}]},{"_type":"block","_key":"afm","style":"normal","children":[{"_type":"span","_key":"afl","text":"[10] As shown in Table 4, the 19 occurrences of the root word “Rashada” are in verses 186, 256, 6, 146, 78, 87, 97, 10, 17, 24, 66, 51, 29, 38, 7, 2, 10, 14, and 21. These are 38 digits = 19×2."}]},{"_type":"block","_key":"afo","style":"normal","children":[{"_type":"span","_key":"afn","text":"[11] Table 4 shows that the sum of the verse numbers where we see the 19 occurrences of the root word “Rashada” is 1145. By adding this total of verse numbers (1145), to the gematrical value of the name “Rashad” (505), plus the gematrical value of the name “Khalifa” (725), we get 1145+505+725 = 2375 = 19×125."}]},{"_type":"block","_key":"afq","style":"normal","children":[{"_type":"span","_key":"afp","text":"[12] If we write down these numbers next to each other, i.e., the total of verse numbers (1145), followed by the gematrical value of the name “Rashad” (505), followed by the gematrical value of the name “Khalifa” (725), we also get a number that is a multiple of 19: 1145505725 = 19×60289775."}]},{"_type":"appendixCallout","_key":"afr","tone":"primary","style":"arithmetic","content":[{"_type":"block","_key":"aft","style":"normal","children":[{"_type":"span","_key":"afs","text":"Sum of Verse Numbers Where the 19 “Rashada” Occur = 1145"}]},{"_type":"block","_key":"afv","style":"normal","children":[{"_type":"span","_key":"afu","text":"Gematrical Value of the Name “Rashad” = 505"}]},{"_type":"block","_key":"afx","style":"normal","children":[{"_type":"span","_key":"afw","text":"Gematrical Value of the Name “Khalifa” = 725"}]},{"_type":"block","_key":"afz","style":"resultSpaced","children":[{"_type":"span","_key":"afy","text":"1145 + 505 + 725 = 2375 = 19 × 125"}]},{"_type":"block","_key":"ag1","style":"result","children":[{"_type":"span","_key":"ag0","text":"1145 505 725 = 1145505725 = 19 × 60289775"}]}]}]$pt$::jsonb, NULL, NULL),

-- Appendix 27: Who Is Your God?
('27', $pt$[{"_type":"block","_key":"a4","style":"normal","children":[{"_type":"span","_key":"a1","text":"Most people are outraged upon hearing this question. “What do you mean, ‘Who is your god?’ they ask, ‘My god is the Creator of the heavens and the earth.’ ” And most of these people will be shocked to find out that their proclamation that their god is the Creator of the heavens and the earth is no more than lip service, and that they are in fact destined for Hell ("},{"_type":"quranRef","_key":"a2","reference":"12:106"},{"_type":"span","_key":"a3","text":")."}]},{"_type":"appendixCallout","_key":"a5","tone":"primary","style":"centeredStatement","content":[{"_type":"block","_key":"a6","style":"normal","bare":true,"children":[{"_type":"span","_key":"a7","text":"Your god is whoever or whatever occupies your mind most of the time."}]}]},{"_type":"block","_key":"ah","style":"normal","children":[{"_type":"span","_key":"a8","text":"Your god can be your children ("},{"_type":"quranRef","_key":"a9","reference":"7:190"},{"_type":"span","_key":"aa","text":"), your spouse ("},{"_type":"quranRef","_key":"ab","reference":"9:24"},{"_type":"span","_key":"ac","text":"), your business ("},{"_type":"quranRef","_key":"ad","reference":"18:35"},{"_type":"span","_key":"ae","text":"), or your ego ("},{"_type":"quranRef","_key":"af","reference":"25:43"},{"_type":"span","_key":"ag","text":"). This is why we note that one of the most important and most repeated commandments in the Quran is:"}]},{"_type":"appendixVerseCards","_key":"al","style":"centerTight","body":"base","refStyle":"plain","entries":[{"_key":"ai","body":{"children":[{"_type":"span","_key":"aj","text":"“O you who believe, you shall remember God frequently; glorify Him day and night.”"}]},"wrapper":"none","reference":{"children":[{"_type":"quranRef","_key":"ak","reference":"33:41"}]}}]},{"_type":"block","_key":"an","style":"normal","children":[{"_type":"span","_key":"am","text":"To put this commandment into practice, we must establish certain habits whereby we guarantee that God occupies our minds more than anything else. The Quran helps us establish such soul saving habits:"}]},{"_type":"appendixDivider","_key":"ao","title":{"children":[{"_type":"span","_key":"ap","text":"Six Habits to Remember God"}]}},{"_type":"appendixBadgeList","_key":"a1m","ordered":true,"style":"badgeMd","item":"badgeBaseline","marker":"primaryCompact","content":"proseFlush","contentTag":"div","items":[{"_key":"aq","content":[{"_type":"block","_key":"av","style":"normal","children":[{"_type":"span","_key":"ar","text":"The Contact Prayers (Salat):","marks":["strong"]},{"_type":"span","_key":"as","text":" those who observe the 5 daily prayers come a long way towards commemorating God a significant proportion of their waking hours. Salat helps us remember God not only during the few minutes of prayer, but also throughout the times of anticipation. At 11:00 AM, one may look at his or her watch to see if the noon prayer is due yet. This act causes one to think about God, and one is credited accordingly ("},{"_type":"quranRef","_key":"at","reference":"20:14"},{"_type":"span","_key":"au","text":")."}]}]},{"_key":"aw","content":[{"_type":"block","_key":"a11","style":"normal","children":[{"_type":"span","_key":"ax","text":"Commemorate God before eating:","marks":["strong"]},{"_type":"span","_key":"ay","text":" Verse "},{"_type":"quranRef","_key":"az","reference":"6:121"},{"_type":"span","_key":"a10","text":" enjoins us to mention God's name before we eat: “You shall not eat from that upon which God's name has not been mentioned.”"}]}]},{"_key":"a12","content":[{"_type":"block","_key":"a17","style":"normal","children":[{"_type":"span","_key":"a13","text":"God Willing (IN SHAA ALLAH):","marks":["strong"]},{"_type":"span","_key":"a14","text":" “You shall not say, ‘I will do this or that tomorrow,’ without saying, ‘God willing’ (IN SHAA ALLAH). If you forget to do this, then apologize and say, ‘May my Lord guide me to do better next time.’” ("},{"_type":"quranRef","_key":"a15","reference":"18:24"},{"_type":"span","_key":"a16","text":"). This is a direct commandment that we must carry out, no matter who we are talking with."}]}]},{"_key":"a18","content":[{"_type":"block","_key":"a1d","style":"normal","children":[{"_type":"span","_key":"a19","text":"God's Gift (MAA SHAA ALLAH):","marks":["strong"]},{"_type":"span","_key":"a1a","text":" To invoke God's protection for our beloved objects - our children, our cars, our homes, etc. - we are enjoined in "},{"_type":"quranRef","_key":"a1b","reference":"18:39"},{"_type":"span","_key":"a1c","text":" to say “MAA SHAA ALLAH” (This is God's gift)."}]}]},{"_key":"a1e","content":[{"_type":"block","_key":"a1h","style":"normal","children":[{"_type":"span","_key":"a1f","text":"Glorify God day and night:","marks":["strong"]},{"_type":"span","_key":"a1g","text":" When we eat anything, we shouldn't be like animals; we must reflect on God's creation of the food we are eating - the flavor, our enjoyment due to the senses God has given us, the perfect packaging of the banana or the orange, the varieties of sea foods created by God, etc. - and glorify Him as we enjoy His provisions. When we see a beautiful flower, or animal, or sunsets, we must glorify God. We must seize every possible opportunity to remember and glorify God, so that God may be our God."}]}]},{"_key":"a1i","content":[{"_type":"block","_key":"a1l","style":"normal","children":[{"_type":"span","_key":"a1j","text":"First Utterance:","marks":["strong"]},{"_type":"span","_key":"a1k","text":" Make it a habit to say: “In the name of God, Most Gracious, Most Merciful. There is no other god besides God,” the moment you wake up every morning. If you establish this good habit, this is what you will utter when you are resurrected."}]}]}]}]$pt$::jsonb, 'gAa7XWY78I8', 'Appendix 27 — Who Is Your God?'),

-- Appendix 28: Muhammad Wrote God's Revelations With His Own Hand
('28', $pt$[{"_type":"appendixVerseCards","_key":"a4","style":"centerTight","body":"base","refStyle":"plain","entries":[{"_key":"a1","body":{"children":[{"_type":"span","_key":"a2","text":"“Read, in the name of your Lord, who created. He created man from an embryo. Read, and your Lord, Most Exalted. Teaches by means of the pen.”"}]},"wrapper":"none","reference":{"children":[{"_type":"quranRef","_key":"a3","reference":"96:1-4"}]}}]},{"_type":"block","_key":"aa","style":"normal","children":[{"_type":"span","_key":"a5","text":"The first revelation was “Read,” and included the statement “God teaches by means of the pen” ("},{"_type":"quranRef","_key":"a6","reference":"96:1-4"},{"_type":"span","_key":"a7","text":"), and the second revelation was “The Pen” ("},{"_type":"quranRef","_key":"a8","reference":"68:1"},{"_type":"span","_key":"a9","text":"). The only function of the pen is to write."}]},{"_type":"block","_key":"ac","style":"normal","children":[{"_type":"span","_key":"ab","text":"Ignorant Muslim scholars of the first two centuries after the Quran could not understand the Quran's challenge to produce anything like it. They had no idea about the Quran's mathematical composition, and they knew that many literary giants could have composed works comparable to the Quran. In fact, many such literary giants did claim the ability to produce a literary work as excellent as the Quran. The latest claim came from Taha Hussein, the renowned Egyptian writer."}]},{"_type":"block","_key":"ae","style":"normal","children":[{"_type":"span","_key":"ad","text":"The ignorant Muslim scholars then decided to proclaim Muhammad an illiterate man! They figured that this would make the Quran's extraordinary literary excellence truly miraculous."}]},{"_type":"appendixDivider","_key":"af","title":{"children":[{"_type":"span","_key":"ag","text":"The Word “Ummy”"}]}},{"_type":"block","_key":"aq","style":"normal","children":[{"_type":"span","_key":"ah","text":"The word they relied on to bestow illiteracy upon the Prophet was “UMMY.” Unfortunately for those “scholars,” this word clearly means “Gentile,” or one who does not follow any scripture (Torah, Injeel, or Quran) — see "},{"_type":"quranRef","_key":"ai","reference":"2:78"},{"_type":"span","_key":"aj","text":", "},{"_type":"quranRef","_key":"ak","reference":"3:20"},{"_type":"span","_key":"al","text":", "},{"_type":"quranRef","_key":"am","reference":"3:75"},{"_type":"span","_key":"an","text":", "},{"_type":"quranRef","_key":"ao","reference":"62:2"},{"_type":"span","_key":"ap","text":". It does NOT mean “illiterate.”"}]},{"_type":"block","_key":"as","style":"normal","children":[{"_type":"span","_key":"ar","text":"The Prophet was a successful merchant. The “Muslim scholars” who fabricated the illiteracy lie forgot that there were no numbers during the Prophet's time — the letters of the alphabet were used as numbers. As a merchant dealing with numbers every day, the Prophet had to know the alphabet, from one to one-thousand."}]},{"_type":"appendixDivider","_key":"at","title":{"children":[{"_type":"span","_key":"au","text":"The Quran's Own Testimony"}]}},{"_type":"block","_key":"a10","style":"normal","children":[{"_type":"span","_key":"av","text":"The Quran tells us that Muhammad wrote down the Quran. His contemporaries are quoted as saying: “These are tales from the past that he wrote down. They are being dictated to him day and night” ("},{"_type":"quranRef","_key":"aw","reference":"25:5"},{"_type":"span","_key":"ax","text":"). You cannot “dictate” to an illiterate person. The Prophet's enemies who accuse him of illiteracy abuse "},{"_type":"quranRef","_key":"ay","reference":"29:48"},{"_type":"span","_key":"az","text":", which relates specifically to previous scriptures."}]},{"_type":"block","_key":"a1c","style":"normal","children":[{"_type":"span","_key":"a11","text":"On the 27th night of Ramadan 13 B.H. (Before Hijerah), Muhammad — the soul, the real person, not the body — was summoned to the highest universe and the Quran was given to him ("},{"_type":"quranRef","_key":"a12","reference":"2:97"},{"_type":"span","_key":"a13","text":", "},{"_type":"quranRef","_key":"a14","reference":"17:1"},{"_type":"span","_key":"a15","text":", "},{"_type":"quranRef","_key":"a16","reference":"44:3"},{"_type":"span","_key":"a17","text":", "},{"_type":"quranRef","_key":"a18","reference":"53:1-18"},{"_type":"span","_key":"a19","text":", "},{"_type":"quranRef","_key":"a1a","reference":"97:1-5"},{"_type":"span","_key":"a1b","text":"). Subsequently, the angel Gabriel helped Muhammad release a few verses of the Quran at a time, from the soul to Muhammad's memory. The Prophet wrote down and memorized the verses just released into his mind."}]},{"_type":"block","_key":"a1j","style":"normal","children":[{"_type":"span","_key":"a1d","text":"When the Prophet died, he left the complete Quran written down with his own hand in the chronological order of revelation, along with specific instructions as to where to place every verse. The divine instructions recorded by the Prophet were designed to put the Quran together into the final format intended for God's Final Testament to the world ("},{"_type":"quranRef","_key":"a1e","reference":"75:17"},{"_type":"span","_key":"a1f","text":"). The early Muslims did not get around to putting the Quran together until the time of Khalifa Rashed ‘Uthmaan. A committee was appointed to carry out this task. Read "},{"_type":"span","_key":"a1h","text":"Appendix 24","marks":["a1g"]},{"_type":"span","_key":"a1i","text":" for the details."}],"markDefs":[{"_key":"a1g","_type":"link","href":"/appendices/24"}]}]$pt$::jsonb, 'XkG1mHWW-QE', 'Appendix 28 — Muhammad Wrote God''s Revelations With His Own Hand'),

-- Appendix 29: The Missing Basmalah
('29', $pt$[{"_type":"block","_key":"a6","style":"normal","children":[{"_type":"span","_key":"a1","text":"Every sura in the Quran opens with the statement “In the name of God, Most Gracious, Most Merciful,” known as the "},{"_type":"span","_key":"a2","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a3","text":", with the exception of Sura 9. This conspicuous absence of the "},{"_type":"span","_key":"a4","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a5","text":" from Sura 9 has been an intriguing feature of the Quran for 14 centuries. Many theories have been advanced to explain this phenomenon."}]},{"_type":"block","_key":"ah","style":"normal","children":[{"_type":"span","_key":"a7","text":"Now we learn that the missing "},{"_type":"span","_key":"a8","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a9","text":" plays a significant role as [1] a significant constituent of the Quran's mathematical miracle, and [2] a glaring sign from the Most Gracious, Most Merciful, that Sura 9 has been tampered with and must be purified ("},{"_type":"span","_key":"ab","text":"Appendix 24","marks":["aa"]},{"_type":"span","_key":"ac","text":"). Both roles of the missing "},{"_type":"span","_key":"ad","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"ae","text":" were revealed with the discovery of the Quran's mathematical code. The following list of factual observations illustrate the miraculous features of the missing "},{"_type":"span","_key":"af","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"ag","text":":"}],"markDefs":[{"_key":"aa","_type":"link","href":"/appendices/24"}]},{"_type":"appendixDivider","_key":"ai","title":{"children":[{"_type":"span","_key":"aj","text":"Twelve Miraculous Features"}]}},{"_type":"block","_key":"at","style":"normal","children":[{"_type":"span","_key":"ak","text":"[1] Since the "},{"_type":"span","_key":"al","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"am","text":" consists of 19 Arabic letters, and prefixes all the suras except one, it can be considered the foundation upon which the Quran's 19-based code is built. But the absence of the "},{"_type":"span","_key":"an","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"ao","text":" from Sura 9 causes the number of this crucial opening statement to be 113, a number that does not conform with the Quran's code. However, we find that this deficiency is compensated for in Sura 27. Two "},{"_type":"span","_key":"ap","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"aq","text":"s occur in Sura 27, one as an opener and one in Verse 30. This restores the total number of "},{"_type":"span","_key":"ar","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"as","text":"s in the Quran to 114 = 19×6."}]},{"_type":"block","_key":"az","style":"normal","children":[{"_type":"span","_key":"au","text":"[2] From the missing "},{"_type":"span","_key":"av","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"aw","text":" of Sura 9 to the extra "},{"_type":"span","_key":"ax","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"ay","text":" of Sura 27, there are 19 suras."}]},{"_type":"block","_key":"a1b","style":"normal","children":[{"_type":"span","_key":"a10","text":"[3] The sum of sura numbers from the missing "},{"_type":"span","_key":"a11","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a12","text":" (Sura 9) to the extra "},{"_type":"span","_key":"a13","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a14","text":" (Sura 27) is 9+10+11+12+…+25+26+27 = 342 = 19×18. This is a mathematical property, any consecutive 19 numbers will add up to a multiple of 19. But the miraculous phenomenon is that this number, 342, equals the number of words from the first "},{"_type":"span","_key":"a15","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a16","text":" of Sura 27 to the second "},{"_type":"span","_key":"a17","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a18","text":" in "},{"_type":"quranRef","_key":"a19","reference":"27:30"},{"_type":"span","_key":"a1a","text":"."}]},{"_type":"block","_key":"a1h","style":"normal","children":[{"_type":"span","_key":"a1c","text":"[4] The occurrence of the extra "},{"_type":"span","_key":"a1d","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a1e","text":" in "},{"_type":"quranRef","_key":"a1f","reference":"27:30"},{"_type":"span","_key":"a1g","text":" conforms with the Quran's code in that the sura number, plus the verse number is a multiple of 19 (27+30 = 57 = 19×3)."}]},{"_type":"block","_key":"a1l","style":"normal","children":[{"_type":"span","_key":"a1i","text":"[5] The occurrence of the extra "},{"_type":"span","_key":"a1j","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a1k","text":" in Verse 30 compares with the occurrence of the number 19 itself in Verse 30 (Sura 74)."}]},{"_type":"block","_key":"a1x","style":"normal","children":[{"_type":"span","_key":"a1m","text":"[6] The Quran contains 6234 numbered verses. The absence of the "},{"_type":"span","_key":"a1n","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a1o","text":" from Sura 9, and compensating for it in Verse 30 of Sura 27 gives us two numbered "},{"_type":"span","_key":"a1p","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a1q","text":"s, "},{"_type":"quranRef","_key":"a1r","reference":"1:1"},{"_type":"span","_key":"a1s","text":" & "},{"_type":"quranRef","_key":"a1t","reference":"27:30"},{"_type":"span","_key":"a1u","text":", and 112 un-numbered "},{"_type":"span","_key":"a1v","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a1w","text":"s. This causes the total number of verses in the Quran to be 6234+112 = 6346 = 19×334."}]},{"_type":"block","_key":"a25","style":"normal","children":[{"_type":"span","_key":"a1y","text":"[7] From the missing "},{"_type":"span","_key":"a1z","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a20","text":" to the extra "},{"_type":"span","_key":"a21","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a22","text":", the number of verses containing the word “Allah” is 513 = 19×27. Note that 27 is the sura number where the extra "},{"_type":"span","_key":"a23","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a24","text":" occurs. The data are in Table 1."}]},{"_type":"appendixDivider","_key":"a26","title":{"children":[{"_type":"span","_key":"a27","text":"Table 1: The Verses Containing the Word “Allah” from the Missing Basmalah to the Extra Basmalah"}]}},{"_type":"appendixGridTable","_key":"a3e","headers":[{"children":[{"_type":"span","_key":"a28","text":"Sura Number"}]},{"children":[{"_type":"span","_key":"a29","text":"Verses w/ “Allah”"}]}],"rows":[{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2a","text":"9"}]}},{"content":{"children":[{"_type":"span","_key":"a2b","text":"100"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2c","text":"10"}]}},{"content":{"children":[{"_type":"span","_key":"a2d","text":"49"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2e","text":"11"}]}},{"content":{"children":[{"_type":"span","_key":"a2f","text":"33"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2g","text":"12"}]}},{"content":{"children":[{"_type":"span","_key":"a2h","text":"34"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2i","text":"13"}]}},{"content":{"children":[{"_type":"span","_key":"a2j","text":"23"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2k","text":"14"}]}},{"content":{"children":[{"_type":"span","_key":"a2l","text":"28"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2m","text":"15"}]}},{"content":{"children":[{"_type":"span","_key":"a2n","text":"2"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2o","text":"16"}]}},{"co