text":"77"}]}},{"content":{"children":[{"_type":"span","_key":"a7i","text":"7"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a7j","text":"26"}]}},{"content":{"children":[{"_type":"span","_key":"a7k","text":"227"}]}},{"content":{"children":[{"_type":"span","_key":"a7l","text":"22"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a7m","text":"27"}]}},{"content":{"children":[{"_type":"span","_key":"a7n","text":"29"}]}},{"content":{"children":[{"_type":"span","_key":"a7o","text":"2"}]}}]},{"variant":"total","cells":[{"content":{"children":[{"_type":"span","_key":"a7p","text":"342 (19×18)"}]}},{"content":{"children":[{"_type":"span","_key":"a7q","text":"1951"}]}},{"content":{"children":[{"_type":"span","_key":"a7r","text":"177"}]}}]}],"notes":[{"children":[{"_type":"span","_key":"a7s","text":"1951 + 177 = 2128 = 19 × 112"}]}]},{"_type":"appendixDivider","_key":"a7u","title":{"children":[{"_type":"span","_key":"a7v","text":"Table 4: The Odd-numbered Suras Whose Number of Verses are also Odd"}]}},{"_type":"appendixGridTable","_key":"a8v","headers":[{"children":[{"_type":"span","_key":"a7w","text":"Sura No."}]},{"children":[{"_type":"span","_key":"a7x","text":"Sum of Digits"}]},{"children":[{"_type":"span","_key":"a7y","text":"No of Verses"}]},{"children":[{"_type":"span","_key":"a7z","text":"Sum of Digits"}]}],"rows":[{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a80","text":"9"}]}},{"content":{"children":[{"_type":"span","_key":"a81","text":"9"}]}},{"content":{"children":[{"_type":"span","_key":"a82","text":"127"}]}},{"content":{"children":[{"_type":"span","_key":"a83","text":"10"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a84","text":"11"}]}},{"content":{"children":[{"_type":"span","_key":"a85","text":"2"}]}},{"content":{"children":[{"_type":"span","_key":"a86","text":"123"}]}},{"content":{"children":[{"_type":"span","_key":"a87","text":"6"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a88","text":"13"}]}},{"content":{"children":[{"_type":"span","_key":"a89","text":"4"}]}},{"content":{"children":[{"_type":"span","_key":"a8a","text":"43"}]}},{"content":{"children":[{"_type":"span","_key":"a8b","text":"7"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a8c","text":"15"}]}},{"content":{"children":[{"_type":"span","_key":"a8d","text":"6"}]}},{"content":{"children":[{"_type":"span","_key":"a8e","text":"99"}]}},{"content":{"children":[{"_type":"span","_key":"a8f","text":"18"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a8g","text":"17"}]}},{"content":{"children":[{"_type":"span","_key":"a8h","text":"8"}]}},{"content":{"children":[{"_type":"span","_key":"a8i","text":"111"}]}},{"content":{"children":[{"_type":"span","_key":"a8j","text":"3"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a8k","text":"25"}]}},{"content":{"children":[{"_type":"span","_key":"a8l","text":"7"}]}},{"content":{"children":[{"_type":"span","_key":"a8m","text":"77"}]}},{"content":{"children":[{"_type":"span","_key":"a8n","text":"14"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a8o","text":"27"}]}},{"content":{"children":[{"_type":"span","_key":"a8p","text":"9"}]}},{"content":{"children":[{"_type":"span","_key":"a8q","text":"29"}]}},{"content":{"children":[{"_type":"span","_key":"a8r","text":"11"}]}}]},{"variant":"total","cells":[{"content":{"children":[]}},{"content":{"children":[{"_type":"span","_key":"a8s","text":"45"}]}},{"content":{"children":[]}},{"content":{"children":[{"_type":"span","_key":"a8t","text":"69"}]}}]}],"notes":[{"children":[{"_type":"span","_key":"a8u","text":"45 + 69 = 114 = 19 × 6"}]}]},{"_type":"block","_key":"a8z","style":"normal","children":[{"_type":"span","_key":"a8w","text":"[11] The next two features authenticate both the missing "},{"_type":"span","_key":"a8x","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a8y","text":" and the number of verses in Sura 9 (where two false verses had been injected). If we take the same suras listed in Table 4, odd-numbered suras whose numbers of verses are also odd, and write down the number of every sura, followed by its number of verses, the resulting long number (30 digits) is a multiple of 19 (Figure 1)."}]},{"_type":"appendixCallout","_key":"a90","tone":"primary","style":"monoStack","content":[{"_type":"block","_key":"a92","style":"center","children":[{"_type":"span","_key":"a91","text":"9 127  11 123  13 43  15 99  17 111  25 77  27 29"}]},{"_type":"block","_key":"a94","style":"centerNote","children":[{"_type":"span","_key":"a93","text":"Every sura number is followed by the number of verses in that sura.\nThis long number = 19 × 48037427533385052195322409091"}]}]},{"_type":"block","_key":"a9a","style":"normal","children":[{"_type":"span","_key":"a95","text":"[12] Let us continue to work with the suras listed in Table 4. They are the odd-numbered suras whose verses are also odd-numbered, from the missing "},{"_type":"span","_key":"a96","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a97","text":" to the extra "},{"_type":"span","_key":"a98","text":"Basmalah","marks":["em"]},{"_type":"span","_key":"a99","text":". If we write down the number of every sura, followed by the last digit in every verse in that sura, we end up with a long number, 1988 digits, which is divisible by 19 (Figure 2)."}]},{"_type":"appendixCallout","_key":"a9b","tone":"primary","style":"monoStack","content":[{"_type":"block","_key":"a9d","style":"center","children":[{"_type":"span","_key":"a9c","text":"9 1234567890123…  …  27 1234567890 … 789"}]},{"_type":"block","_key":"a9f","style":"centerNote","children":[{"_type":"span","_key":"a9e","text":"The sura number is followed by the last digit in every verse number."}]}]}]$pt$::jsonb, NULL, NULL),

-- Appendix 30: Polygamy
('30', $pt$[{"_type":"block","_key":"a2","style":"normal","children":[{"_type":"span","_key":"a1","text":"Polygamy was a way of life until the Quran was revealed 1400 years ago. When the earth was young and under-populated, polygamy was one way of populating it and bringing in the human beings needed to carry out God's plan. By the time the Quran was revealed, the world had been sufficiently populated, and the Quran put down the first limitations against polygamy."}]},{"_type":"block","_key":"a4","style":"normal","children":[{"_type":"span","_key":"a3","text":"Polygamy is permitted in the Quran, but under strictly observed circumstances. Any abuse of this divine permission incurs severe retribution. Thus, although polygamy is permitted by God, it behooves us to examine our circumstances carefully before saying that a particular polygamous relationship is permissible."}]},{"_type":"appendixDivider","_key":"a5","title":{"children":[{"_type":"span","_key":"a6","text":"The Prophet's Example"}]}},{"_type":"block","_key":"a8","style":"normal","children":[{"_type":"span","_key":"a7","text":"Our perfect example here is the prophet Muhammad. He was married to one wife, Khadijah, until she died. He had all his children, except one, from Khadijah. Thus, she and her children enjoyed the Prophet's full attention for as long as she was married to him — twenty-five years. For all practical purposes, Muhammad had one wife from the age of 25 to 50."}]},{"_type":"block","_key":"ac","style":"normal","children":[{"_type":"span","_key":"a9","text":"During the remaining 13 years of his life, he married the aged widows of his friends who left many children. The children needed a complete home with a fatherly figure, and the Prophet provided that. Providing a fatherly figure for orphans is the only specific circumstance in support of polygamy mentioned in the Quran ("},{"_type":"quranRef","_key":"aa","reference":"4:3"},{"_type":"span","_key":"ab","text":")."}]},{"_type":"block","_key":"ae","style":"normal","children":[{"_type":"span","_key":"ad","text":"Other than marrying widowed mothers of orphans, there were three political marriages in the Prophet's life. His close friends Abu Bakr and Omar insisted that he marry their daughters, Aisha and Hafsah, to establish traditional family ties among them. The third marriage was to Maria the Egyptian; she was given to him as a political gesture of friendship from the ruler of Egypt."}]},{"_type":"block","_key":"ag","style":"normal","children":[{"_type":"span","_key":"af","text":"This perfect example tells us that a man must give his full attention and loyalty in marriage to his wife and children in order to raise a happy and wholesome family."}]},{"_type":"appendixDivider","_key":"ah","title":{"children":[{"_type":"span","_key":"ai","text":"The Quranic Limitations"}]}},{"_type":"block","_key":"ak","style":"normal","children":[{"_type":"span","_key":"aj","text":"The Quran emphasizes the limitations against polygamy in very strong words:"}]},{"_type":"block","_key":"ao","style":"normal","children":[{"_type":"span","_key":"al","text":"“If you fear lest you may not be perfectly equitable in treating more than one wife, then you shall be content with one.” ("},{"_type":"quranRef","_key":"am","reference":"4:3"},{"_type":"span","_key":"an","text":")"}]},{"_type":"block","_key":"as","style":"normal","children":[{"_type":"span","_key":"ap","text":"“You cannot be equitable in a polygamous relationship, no matter how hard you try.” ("},{"_type":"quranRef","_key":"aq","reference":"4:129"},{"_type":"span","_key":"ar","text":")"}]},{"_type":"block","_key":"au","style":"normal","children":[{"_type":"span","_key":"at","text":"The Quranic limitations against polygamy point out the possibility of abusing God's law. Therefore, unless we are absolutely sure that God's law will not be abused, we had better resist our lust and stay away from polygamy. If the circumstances do not dictate polygamy, we had better give our full attention to one wife and one set of children. The children's psychological and social well-being, especially in countries where polygamy is prohibited, almost invariably dictate monogamy. A few basic criteria must be observed in contemplating polygamy:"}]},{"_type":"appendixDivider","_key":"av","title":{"children":[{"_type":"span","_key":"aw","text":"Basic Criteria"}]}},{"_type":"appendixBadgeList","_key":"a15","ordered":true,"style":"badgeSm","item":"badgeBaseline","marker":"primaryCompact","content":"base","contentTag":"p","items":[{"_key":"ax","text":{"children":[{"_type":"span","_key":"ay","text":"It must alleviate pain and suffering and not cause any pain or suffering."}]}},{"_key":"az","text":{"children":[{"_type":"span","_key":"a10","text":"If you have a young family, it is almost certain that polygamy is an abuse."}]}},{"_key":"a11","text":{"children":[{"_type":"span","_key":"a12","text":"Polygamy to substitute a younger wife is an abuse of God's law ("},{"_type":"quranRef","_key":"a13","reference":"4:19"},{"_type":"span","_key":"a14","text":")."}]}}]}]$pt$::jsonb, 'OTYzP1BgWow', 'Appendix 30 — Polygamy'),

-- Appendix 31: Evolution: A Divinely Guided Process
('31', $pt$[{"_type":"block","_key":"a2","style":"normal","children":[{"_type":"span","_key":"a1","text":"We learn from the Quran that evolution is a divinely designed fact:"}]},{"_type":"appendixCallout","_key":"a3","tone":"primary","style":"exampleWide","content":[{"_type":"appendixSection","_key":"ac","style":"stackFlush","tag":"div","content":[{"_type":"block","_key":"a5","style":"term","children":[{"_type":"span","_key":"a4","text":"Life began in water"}]},{"_type":"block","_key":"ab","style":"body","children":[{"_type":"span","_key":"a6","text":"“From water we initiated all living things.” ("},{"_type":"quranRef","_key":"a7","reference":"21:30"},{"_type":"span","_key":"a8","text":", "},{"_type":"quranRef","_key":"a9","reference":"24:45"},{"_type":"span","_key":"aa","text":")"}]}]},{"_type":"appendixSection","_key":"aj","style":"stackFlush","tag":"div","content":[{"_type":"block","_key":"ae","style":"term","children":[{"_type":"span","_key":"ad","text":"Humans not descendants of monkeys"}]},{"_type":"block","_key":"ai","style":"body","children":[{"_type":"span","_key":"af","text":"“He started the creation of man from mud.” ("},{"_type":"quranRef","_key":"ag","reference":"32:7"},{"_type":"span","_key":"ah","text":")"}]}]},{"_type":"appendixSection","_key":"aq","style":"stackFlush","tag":"div","content":[{"_type":"block","_key":"al","style":"term","children":[{"_type":"span","_key":"ak","text":"Man created from “aged” mud"}]},{"_type":"block","_key":"ap","style":"body","children":[{"_type":"span","_key":"am","text":"“I am creating the human being from ‘aged’ clay.” ("},{"_type":"quranRef","_key":"an","reference":"15:28"},{"_type":"span","_key":"ao","text":")"}]}]}]},{"_type":"block","_key":"as","style":"normal","children":[{"_type":"span","_key":"ar","text":"Evolution is possible only within a given species. For example, the navel orange evolved from seeded oranges, not from apples. The laws of probability preclude the possibility of haphazard evolution between species. A fish cannot evolve into a bird; a monkey can never evolve into a human."}]},{"_type":"appendixDivider","_key":"at","title":{"children":[{"_type":"span","_key":"au","text":"Probability Laws Preclude Darwin's Evolution"}]}},{"_type":"block","_key":"aw","style":"normal","children":[{"_type":"span","_key":"av","text":"In this computer age, we have mathematical laws that tell us whether a certain event is probable or not. If we throw five numbered cubes up in the air and let them fall into a guided straight line, the probability laws tell us the number of possible combinations we can get: 1×2×3×4×5 = 120 combinations. Thus, the probability of obtaining any combination is 1 in 120, or 1/120, or 0.0086."}]},{"_type":"block","_key":"ay","style":"normal","children":[{"_type":"span","_key":"ax","text":"This probability diminishes fast when we increase the number of cubes. If we increase them by one, the number of combinations becomes 1×2×3×4×5×6 = 720, and the probability of getting any combination diminishes to 1/720, 0.0014. Mathematicians, who are very exacting scientists, have agreed that the probability diminishes to “Zero” when we increase the number of cubes to 84. If we work with 84 cubes, the probability diminishes to 209×10⁻⁵⁰, or 0.00000000000000000000000000000000000000000000000000209"}]},{"_type":"block","_key":"a10","style":"normal","children":[{"_type":"span","_key":"az","text":"Darwin's famous statement that “life began as a ‘simple’ cell” is laughable. As recently as 50 years ago, Wells, Huxley, and Wells wrote in their classic textbook that “nothing can be seen inside the nucleus but clear fluid.” We know now that the cell is an extremely complex unit, with billions of nucleotides in the gene material inside the nucleus, and millions of biochemical reactions. The probability laws tell us that the probability of the haphazard creation of the exacting sequences of nucleotides into DNA is Zero, many times over. We are not talking about 84 nucleotides; we are talking about billions of nucleotides that must be arranged in a specific sequence."}]},{"_type":"block","_key":"a12","style":"normal","children":[{"_type":"span","_key":"a11","text":"Some evolutionists have stated that the human gene and the monkey's gene are 90% similar. However, even if the similarity was 99%, we are still talking about 300,000,000 nucleotides that must be haphazardly re-arranged to change the monkey into a human. The probability laws preclude this as an utter impossibility. The human gene contains 30,000,000,000 nucleotides; 1% of that is 300,000,000."}]},{"_type":"block","_key":"a14","style":"normal","children":[{"_type":"span","_key":"a13","text":"A fitting quote here is that of Professor Edwin Conklin; he stated:"}]},{"_type":"appendixCallout","_key":"a15","tone":"primary","style":"quotationTight","content":[{"_type":"block","_key":"a17","style":"normal","children":[{"_type":"span","_key":"a16","text":"The probability of life originating from accident is comparable to the probability of the Unabridged Dictionary resulting from an explosion in a printing factory."}]}]}]$pt$::jsonb, '3HN_sTndr04', 'Appendix 31 — Evolution: Divinely Controlled'),

-- Appendix 32: The Crucial Age of 40
('32', $pt$[{"_type":"block","_key":"a2","style":"normal","children":[{"_type":"span","_key":"a1","text":"What is the age of responsibility? If a child dies at the age of 12, without even hearing about God, does this child go to Heaven or Hell? What if the child is 15 years old, or 21, or 25? At what age will the human being be held responsible for his or her beliefs? This question has puzzled researchers of all religions for a long time."}]},{"_type":"block","_key":"a9","style":"normal","children":[{"_type":"span","_key":"a3","text":"The Quran sets the age of responsibility at 40; anyone who dies before this age goes to Heaven ("},{"_type":"quranRef","_key":"a4","reference":"46:15"},{"_type":"span","_key":"a5","text":"). If the person believed in God and benefitted from belief by nourishing and developing the soul (see "},{"_type":"span","_key":"a7","text":"Appendix 15","marks":["a6"]},{"_type":"span","_key":"a8","text":"), he or she goes to the High Heaven. Otherwise, the person goes to the Lower Heaven."}],"markDefs":[{"_key":"a6","_type":"link","href":"/appendices/15"}]},{"_type":"appendixDivider","_key":"aa","title":{"children":[{"_type":"span","_key":"ab","text":"God's Mercy"}]}},{"_type":"block","_key":"ad","style":"normal","children":[{"_type":"span","_key":"ac","text":"Your first reaction to this piece of information is objection: “What if the person was really bad, evil, and an atheist, will he go to Heaven if he died before the age of 40?” This is because you are mean, while God is the Most Merciful. Our tendency is to “put them all in Hell.”"}]},{"_type":"block","_key":"af","style":"normal","children":[{"_type":"span","_key":"ae","text":"People who objected strongly to this Divine mercy cannot come up with a cut-off age of responsibility. They ask questions like, “What if the person was really wicked?” The answer is, “Does God know that this person was wicked?” “Yes.” “Does God know that this person does not deserve to go to Heaven?” “Yes.” “Therefore, this person will not die before the age of 40.” As simple as that. God is the only one who terminates our lives on this earth. He knows exactly who deserves to go to Heaven and who deserves to go to Hell."}]},{"_type":"appendixDivider","_key":"ag","title":{"children":[{"_type":"span","_key":"ah","text":"A Confirming Sign"}]}},{"_type":"block","_key":"aj","style":"normal","children":[{"_type":"span","_key":"ai","text":"Early in 1989 a man by the name of Theodore Robert Bundy was executed for killing a number of women. The whole nation agreed that he was one of the most vicious criminals in history. So much so that his execution was one of the rare occasions where the opponents of capital punishment did not protest. On the contrary, many people actually celebrated his execution. Numerous journalists, editorials, and politicians lamented the fact that justice took eleven years to execute Ted Bundy. They stated that Bundy should have been executed within a maximum of six years after his conviction. According to the Quran, this would have been the greatest favor anyone could have done to Bundy. He was 42 years old when executed. Had he been executed five years earlier, at the age of 37, he would have gone straight to Heaven, and he did not deserve that."}]},{"_type":"block","_key":"al","style":"normal","children":[{"_type":"span","_key":"ak","text":"As it turns out, Bundy was one of the signs God has given us to confirm that anyone who dies before 40 goes to Heaven. Bundy's name, Theodore Robert Bundy, consists of 19 letters, and he confessed to killing 19 women just one day before his execution. There were many other signs from God."}]},{"_type":"block","_key":"an","style":"normal","children":[{"_type":"span","_key":"am","text":"Delivering this important piece of information is one of the responsibilities given to me as God's Messenger of the Covenant. It is not my personal opinion."}]},{"_type":"block","_key":"ap","style":"normal","children":[{"_type":"span","_key":"ao","text":"It is noteworthy that both Martin Luther King and Malcolm X were assassinated just a couple of months before their 40th birthdays."}]}]$pt$::jsonb, 'J53TKCcic8I', 'Appendix 32 — The Crucial Age of 40'),

-- Appendix 33: Why Did God Send a Messenger Now?
('33', $pt$[{"_type":"appendixSection","_key":"af","style":"prose","tag":"section","content":[{"_type":"block","_key":"a7","style":"normal","children":[{"_type":"span","_key":"a1","text":"As stated in "},{"_type":"quranRef","_key":"a2","reference":"3:81"},{"_type":"span","_key":"a3","text":", and in "},{"_type":"span","_key":"a5","text":"Appendix 2","marks":["a4"]},{"_type":"span","_key":"a6","text":", God has sent a messenger to consolidate the messages delivered by all the prophets, purify them, and unify them into one religion: Submission. The timing is certainly ripe for fulfillment of this important prophecy, for the following reasons:"}],"markDefs":[{"_key":"a4","_type":"link","href":"/appendices/2"}]},{"_type":"appendixBadgeList","_key":"ae","ordered":true,"style":"badge","item":"badgeBaseline","marker":"primaryCompact","content":"none","contentTag":"p","items":[{"_key":"a8","text":{"children":[{"_type":"span","_key":"a9","text":"Judaism, Christianity, and Islam have been corrupted beyond recognition."}]}},{"_key":"aa","text":{"children":[{"_type":"span","_key":"ab","text":"All God's messages have been delivered; the Quran is the Final Testament."}]}},{"_key":"ac","text":{"children":[{"_type":"span","_key":"ad","text":"More than 93% of the human beings destined to live in this world are yet to come. As illustrated in the Introduction, the people who have lived on this earth since Adam are only one-fifteenth of the total projected human population."}]}}]}]},{"_type":"appendixDivider","_key":"ag","title":{"children":[{"_type":"span","_key":"ah","text":"Judaism"}]}},{"_type":"block","_key":"al","style":"normal","children":[{"_type":"span","_key":"ai","text":"The best illustration of today's corrupted Judaism can be found in the books of a famous Rabbi; Harold S. Kushner. In his best seller "},{"_type":"span","_key":"aj","text":"When Bad Things Happen to Good People","marks":["em"]},{"_type":"span","_key":"ak","text":", Avon Books, 1981, Rabbi Kushner states the following:"}]},{"_type":"appendixCallout","_key":"am","tone":"primary","style":"quotation","content":[{"_type":"block","_key":"ao","style":"normal","children":[{"_type":"span","_key":"an","text":"“…, we would be advised to take this world as seriously as we can, in case it turns out to be the only one we will ever have, and to look for meaning and justice here. (P. 29)”"}]},{"_type":"block","_key":"aq","style":"normal","children":[{"_type":"span","_key":"ap","text":"“Bad things do happen to good people in this world, but it is not God who wills it. God would like people to get what they deserve, but He cannot always arrange it. (P. 42)”"}]},{"_type":"block","_key":"as","style":"normal","children":[{"_type":"span","_key":"ar","text":"“God does not reach down to interrupt the workings of laws of nature to protect the righteous from harm. This is a second area of our world which causes bad things to happen to good people, and God does not cause it and cannot stop it. (P. 58)”"}]},{"_type":"block","_key":"au","style":"normal","children":[{"_type":"span","_key":"at","text":"“God can't do everything, but He can do some important things. (P. 113)”"}]},{"_type":"block","_key":"aw","style":"normal","children":[{"_type":"span","_key":"av","text":"“We can't ask Him to make us immune to disease, because He can't do that. (P. 125)”"}]},{"_type":"block","_key":"ay","style":"normal","children":[{"_type":"span","_key":"ax","text":"“I recognize His limitations. He is limited in what He can do by law of nature, and by the evolution of human nature and human moral freedom. (P. 134)”"}]}]},{"_type":"appendixDivider","_key":"az","title":{"children":[{"_type":"span","_key":"a10","text":"Christianity"}]}},{"_type":"block","_key":"a14","style":"normal","children":[{"_type":"span","_key":"a11","text":"If Jesus came back to life today, the Christians would crucify him. Outstanding Christian scholars have reached solid conclusions that today's Christianity has nothing to do with Jesus, and that its doctrine was mortally distorted at the infamous Nicene Conferences (325 A.D.). See "},{"_type":"span","_key":"a12","text":"The Myth of God Incarnate","marks":["em"]},{"_type":"span","_key":"a13","text":", Westminster Press, Philadelphia, 1977."}]},{"_type":"appendixDivider","_key":"a15","title":{"children":[{"_type":"span","_key":"a16","text":"Islam"}]}},{"_type":"block","_key":"a1h","style":"normal","children":[{"_type":"span","_key":"a17","text":"If Muhammad came back to this world, the “Muslims” would stone him to death. The religion they follow today has nothing to do with the Islam, i.e., Submission, preached by Abraham and Muhammad. Everything the “Muslims” do is wrong: the First Pillar (Shahaadah), the call to Salat prayer (Azan), the ablution (Wudu), the daily Salat prayers, the Zakat charity, Hajj, and all other practices of Islam (see "},{"_type":"span","_key":"a19","text":"Appendices 2","marks":["a18"]},{"_type":"span","_key":"a1a","text":", "},{"_type":"span","_key":"a1c","text":"13","marks":["a1b"]},{"_type":"span","_key":"a1d","text":", & "},{"_type":"span","_key":"a1f","text":"15","marks":["a1e"]},{"_type":"span","_key":"a1g","text":")."}],"markDefs":[{"_key":"a18","_type":"link","href":"/appendices/2"},{"_key":"a1b","_type":"link","href":"/appendices/13"},{"_key":"a1e","_type":"link","href":"/appendices/15"}]},{"_type":"appendixDivider","_key":"a1i","title":{"children":[{"_type":"span","_key":"a1j","text":"“A Religion Never Authorized by God” ("},{"_type":"quranRef","_key":"a1k","reference":"42:21"},{"_type":"span","_key":"a1l","text":")"}]}},{"_type":"block","_key":"a1n","style":"normal","children":[{"_type":"span","_key":"a1m","text":"The extent to which Islam has been corrupted is illustrated in the following table:"}]},{"_type":"appendixGridTable","_key":"a67","headers":[{"children":[{"_type":"span","_key":"a1o","text":"Innovation"}]},{"children":[{"_type":"span","_key":"a1p","text":"Violated Quranic Principles"}]}],"rows":[{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a1q","text":"Hadith & Sunna"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a1r","reference":"6:19"},{"_type":"span","_key":"a1s","text":", "},{"_type":"quranRef","_key":"a1t","reference":"6:38"},{"_type":"span","_key":"a1u","text":", "},{"_type":"quranRef","_key":"a1v","reference":"6:114"},{"_type":"span","_key":"a1w","text":"; "},{"_type":"quranRef","_key":"a1x","reference":"7:1-3"},{"_type":"span","_key":"a1y","text":"; "},{"_type":"quranRef","_key":"a1z","reference":"12:111"},{"_type":"span","_key":"a20","text":"; "},{"_type":"quranRef","_key":"a21","reference":"17:46"},{"_type":"span","_key":"a22","text":"; "},{"_type":"quranRef","_key":"a23","reference":"31:6"},{"_type":"span","_key":"a24","text":"; "},{"_type":"quranRef","_key":"a25","reference":"45:6"},{"_type":"span","_key":"a26","text":"; "},{"_type":"quranRef","_key":"a27","reference":"69:38-47"},{"_type":"span","_key":"a28","text":"; plus more."}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a29","text":"Killing whomever they consider an apostate"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a2a","reference":"2:256"},{"_type":"span","_key":"a2b","text":"; "},{"_type":"quranRef","_key":"a2c","reference":"4:90"},{"_type":"span","_key":"a2d","text":"; "},{"_type":"quranRef","_key":"a2e","reference":"10:99"},{"_type":"span","_key":"a2f","text":"; "},{"_type":"quranRef","_key":"a2g","reference":"18:29"},{"_type":"span","_key":"a2h","text":"; "},{"_type":"quranRef","_key":"a2i","reference":"88:21-22"}]}}]},{"variant":"group","cells":[{"content":{"children":[{"_type":"span","_key":"a2j","text":"Vicious criminal justice system:"}]},"colSpan":2}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2k","text":"Cutting off the hand of the thief"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a2l","reference":"5:38"},{"_type":"span","_key":"a2m","text":", "},{"_type":"quranRef","_key":"a2n","reference":"12:31"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2o","text":"Stoning the adulterers to death"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a2p","reference":"24:2"},{"_type":"span","_key":"a2q","text":", "},{"_type":"quranRef","_key":"a2r","reference":"4:25"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2s","text":"Killing anyone who does not observe Salat"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a2t","reference":"2:256"},{"_type":"span","_key":"a2u","text":", "},{"_type":"quranRef","_key":"a2v","reference":"18:29"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a2w","text":"Killing one who drinks alcohol for the 4th time"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a2x","reference":"2:256"},{"_type":"span","_key":"a2y","text":", "},{"_type":"quranRef","_key":"a2z","reference":"18:29"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a30","text":"Forbidding menstruating women from worshiping"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a31","reference":"2:222"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a32","text":"Forbidding women from the Friday Prayer"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a33","reference":"62:9"}]}}]},{"variant":"group","cells":[{"content":{"children":[{"_type":"span","_key":"a34","text":"Idolizing Muhammad against his will:"}]},"colSpan":2}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a35","text":"calling him “the most honorable messenger”"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a36","reference":"2:285"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a37","text":"claiming that he was infallible"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a38","reference":"4:79"},{"_type":"span","_key":"a39","text":"; "},{"_type":"quranRef","_key":"a3a","reference":"9:117"},{"_type":"span","_key":"a3b","text":"; "},{"_type":"quranRef","_key":"a3c","reference":"17:73-74"},{"_type":"span","_key":"a3d","text":"; "},{"_type":"quranRef","_key":"a3e","reference":"33:37"},{"_type":"span","_key":"a3f","text":"; "},{"_type":"quranRef","_key":"a3g","reference":"40:66"},{"_type":"span","_key":"a3h","text":", "},{"_type":"quranRef","_key":"a3i","reference":"66:1"},{"_type":"span","_key":"a3j","text":"; "},{"_type":"quranRef","_key":"a3k","reference":"80:1-10"},{"_type":"span","_key":"a3l","text":"; "},{"_type":"quranRef","_key":"a3m","reference":"93:7"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a3n","text":"setting up his tomb as a “Sacred Mosque”"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a3o","reference":"2:149-150"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a3p","text":"claiming that he possesses power of intercession"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a3q","reference":"2:48"},{"_type":"span","_key":"a3r","text":", "},{"_type":"quranRef","_key":"a3s","reference":"2:123"},{"_type":"span","_key":"a3t","text":", "},{"_type":"quranRef","_key":"a3u","reference":"2:254"},{"_type":"span","_key":"a3v","text":"; "},{"_type":"quranRef","_key":"a3w","reference":"6:70"},{"_type":"span","_key":"a3x","text":", "},{"_type":"quranRef","_key":"a3y","reference":"6:94"},{"_type":"span","_key":"a3z","text":"; "},{"_type":"quranRef","_key":"a40","reference":"7:53"},{"_type":"span","_key":"a41","text":"; "},{"_type":"quranRef","_key":"a42","reference":"10:3"},{"_type":"span","_key":"a43","text":"; "},{"_type":"quranRef","_key":"a44","reference":"39:44"},{"_type":"span","_key":"a45","text":"; "},{"_type":"quranRef","_key":"a46","reference":"43:86"},{"_type":"span","_key":"a47","text":"; "},{"_type":"quranRef","_key":"a48","reference":"74:48"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a49","text":"Inventing an indefensible story about his ascension to the heavens on a horse, at the speed of light, and talking God out of 50 Salat prayers. At the speed of light, he would still be traveling within the Milky Way Galaxy."}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4a","reference":"17:1"},{"_type":"span","_key":"a4b","text":"; "},{"_type":"quranRef","_key":"a4c","reference":"53:1-18"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4d","text":"Adding his name in the Salat prayers & Azan"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4e","reference":"20:14"},{"_type":"span","_key":"a4f","text":"; "},{"_type":"quranRef","_key":"a4g","reference":"72:18"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4h","text":"Adding his name to the First Pillar of Islam"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4i","reference":"3:18"},{"_type":"span","_key":"a4j","text":"; "},{"_type":"quranRef","_key":"a4k","reference":"37:35"},{"_type":"span","_key":"a4l","text":"; "},{"_type":"quranRef","_key":"a4m","reference":"39:45"}]}}]},{"variant":"group","cells":[{"content":{"children":[{"_type":"span","_key":"a4n","text":"Insulting Muhammad by depicting him as a vicious man:"}]},"colSpan":2}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4o","text":"they claim he gouged out people's eyes"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4p","reference":"3:159"},{"_type":"span","_key":"a4q","text":"; "},{"_type":"quranRef","_key":"a4r","reference":"68:4"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4s","text":"Claiming he possessed sexual power of 30 men"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4t","reference":"18:110"},{"_type":"span","_key":"a4u","text":"; "},{"_type":"quranRef","_key":"a4v","reference":"25:20"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4w","text":"Nullifying the fact that Muhammad was the last prophet by teaching that Jesus will come back to this world. This makes Jesus the last prophet."}]}},{"content":{"children":[{"_type":"quranRef","_key":"a4x","reference":"33:40"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a4y","text":"Claiming that Muhammad was illiterate, un-intelligent."}]}},{"content":{"children":[{"_type":"span","_key":"a4z","text":"See "},{"_type":"span","_key":"a51","text":"Appendix 28","marks":["a50"]}],"markDefs":[{"_key":"a50","_type":"link","href":"/appendices/28"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a52","text":"A bizarre dietary system with multitudes of prohibitions"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a53","reference":"6:145-150"},{"_type":"span","_key":"a54","text":"; "},{"_type":"quranRef","_key":"a55","reference":"16:115-116"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a56","text":"Altering the Sacred Months"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a57","reference":"9:37"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a58","text":"Neglecting the Zakat charity through distortion"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a59","reference":"6:141"},{"_type":"span","_key":"a5a","text":", "},{"_type":"span","_key":"a5c","text":"Appendix 15","marks":["a5b"]}],"markDefs":[{"_key":"a5b","_type":"link","href":"/appendices/15"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a5d","text":"Oppressing women and forcing them to wear head-covers and unreasonable clothes; and depriving them of all rights in marriage, divorce, inheritance, etc."}]}},{"content":{"children":[{"_type":"quranRef","_key":"a5e","reference":"2:228"},{"_type":"span","_key":"a5f","text":"; "},{"_type":"quranRef","_key":"a5g","reference":"3:195"},{"_type":"span","_key":"a5h","text":"; "},{"_type":"quranRef","_key":"a5i","reference":"4:19"},{"_type":"span","_key":"a5j","text":", "},{"_type":"quranRef","_key":"a5k","reference":"4:32"},{"_type":"span","_key":"a5l","text":"; "},{"_type":"quranRef","_key":"a5m","reference":"9:71"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a5n","text":"Insulting women by instituting that “if a monkey, dog, or a woman passes in front of a praying person, his prayer is nullified” (Hadith)"}]}},{"content":{"children":[]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a5o","text":"Inventing numerous rules from ablution, to prayer, to sleeping, to cutting one's nails"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a5p","reference":"5:101"},{"_type":"span","_key":"a5q","text":"; "},{"_type":"quranRef","_key":"a5r","reference":"42:21"},{"_type":"span","_key":"a5s","text":"; "},{"_type":"quranRef","_key":"a5t","reference":"2:67-71"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a5u","text":"Prohibiting gold and silk for men"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a5v","reference":"5:48-49"},{"_type":"span","_key":"a5w","text":"; "},{"_type":"quranRef","_key":"a5x","reference":"7:31-32"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a5y","text":"Prohibiting music and the arts"}]}},{"content":{"children":[{"_type":"quranRef","_key":"a5z","reference":"7:32"},{"_type":"span","_key":"a60","text":"; "},{"_type":"quranRef","_key":"a61","reference":"34:13"},{"_type":"span","_key":"a62","text":"; "},{"_type":"quranRef","_key":"a63","reference":"42:21"}]}}]},{"variant":"data","cells":[{"content":{"children":[{"_type":"span","_key":"a64","text":"Ridiculing Islam by stating that the earth is built on top of a giant whale!! ("},{"_type":"quranRef","_key":"a65","reference":"79:30"},{"_type":"span","_key":"a66","text":"; Ibn Kathir, 1200 AD & Ben Baz, 1975 AD)"}]}},{"content":{"children":[]}}]}]},{"_type":"block","_key":"a69","style":"normal","children":[{"_type":"span","_key":"a68","text":"This is only a minute sample of the violations committed by the “Muslims” on a daily basis. This is why God has sent His Messenger of the Covenant now."}]}]$pt$::jsonb, 'qaJTFggUvDU', 'Appendix 33 — Why Did God Send A Messenger Now?'),

-- Appendix 34: Virginity/Chastity: A Trait of the True Believers
('34', $pt$[{"_type":"appendixCallout","_key":"a1","tone":"primary","style":"plain","content":[{"_type":"block","_key":"ab","style":"normal","children":[{"_type":"span","_key":"a2","text":"Sons and daughters of the true believers must be taught that their happiness throughout their lives depends on following God's law and preserving their chastity. This means that they must keep themselves for their spouses only, and never allow anyone else to touch them in a sexual manner ("},{"_type":"quranRef","_key":"a3","reference":"23:5-6"},{"_type":"span","_key":"a4","text":", "},{"_type":"quranRef","_key":"a5","reference":"24:30"},{"_type":"span","_key":"a6","text":", "},{"_type":"quranRef","_key":"a7","reference":"33:35"},{"_type":"span","_key":"a8","text":", "},{"_type":"quranRef","_key":"a9","reference":"70:29-30"},{"_type":"span","_key":"aa","text":")."}]}]},{"_type":"block","_key":"ad","style":"normal","children":[{"_type":"span","_key":"ac","text":"Today's society is replete with powerful temptations. In America's society of the eighties, even parents start talking about boyfriends for their daughters and girlfriends for their sons. When they reach their teens, many parents even supply birth control means to their children. An alarming percentage of teen-agers are sexually active, even though they are not physiologically mature, and without any moral limitations. Millions of illicit pregnancies and the tragedies associated with them, plus millions of tragic abortions, happen every month in the USA."}]},{"_type":"block","_key":"af","style":"normal","children":[{"_type":"span","_key":"ae","text":"Among the results of this moral breakdown: unwanted and unsupported children, delinquent and irresponsible fathers, criminals who have no regard for people's lives or properties, millions of social misfits, incurable genital herpes, incurable genital warts, devastating syphilis and gonorrhea, dysplasia, the killer AIDS, and new diseases never known before."}]},{"_type":"block","_key":"aj","style":"normal","children":[{"_type":"span","_key":"ag","text":"What most people do not know is that this moral breakdown costs them dearly throughout their lives. For the only law that rules the world is God's law, and these flagrant violations of God's law cost them a lot of misery and problems ("},{"_type":"quranRef","_key":"ah","reference":"20:124"},{"_type":"span","_key":"ai","text":")."}]},{"_type":"block","_key":"ar","style":"normal","children":[{"_type":"span","_key":"ak","text":"The true believers who care about their children will advise them and remind them repeatedly and persistently ("},{"_type":"quranRef","_key":"al","reference":"20:132"},{"_type":"span","_key":"am","text":") to keep their chastity. This means staying virgin until their wedding night, then staying loyal to one's spouse — never committing adultery — for their own happiness. God's advice to keep our chastity, before and after marriage, is for our own good. God is the one who controls our health, wealth, and happiness or misery ("},{"_type":"quranRef","_key":"an","reference":"53:43"},{"_type":"span","_key":"ao","text":", "},{"_type":"quranRef","_key":"ap","reference":"53:48"},{"_type":"span","_key":"aq","text":")."}]}]$pt$::jsonb, 'M84OWAjOYdQ', 'Appendix 34 — Virginity'),

-- Appendix 35: Drugs & Alcohol
('35', $pt$[{"_type":"block","_key":"a8","style":"normal","children":[{"_type":"span","_key":"a1","text":"There is no compromise whatsoever regarding illicit drugs and alcoholic beverages; they are called “abominations and the work of Satan” ("},{"_type":"quranRef","_key":"a2","reference":"5:90"},{"_type":"span","_key":"a3","text":"). In "},{"_type":"quranRef","_key":"a4","reference":"2:219"},{"_type":"span","_key":"a5","text":" and "},{"_type":"quranRef","_key":"a6","reference":"5:90"},{"_type":"span","_key":"a7","text":", we see that “intoxicants, gambling, the idols' altars, and games of chance” are strictly prohibited."}]},{"_type":"block","_key":"aa","style":"normal","children":[{"_type":"span","_key":"a9","text":"The word used for intoxicants is “Khamr” from the root word “Khamara” which means “to cover.” Thus, anything that covers or hinders the mind is prohibited. This includes anything that alters the mind, such as marijuana, heroin, cocaine, alcohol, hashish, and anything else that affects the mind."}]}]$pt$::jsonb, 'UNYn4b_65_Q', 'Appendix 35 — Drugs & Alcohol'),

-- Appendix 36: What Price A Great Nation
('36', $pt$[{"_type":"appendixCallout","_key":"a1","tone":"primary","style":"plainStack","content":[{"_type":"block","_key":"a5","style":"normal","children":[{"_type":"span","_key":"a2","text":"“If the people of the scripture (Jews, Christians, and Muslims) believe and maintain a righteous life, we will remit their sins and admit them into the blissful Heaven. Had they observed the Torah, the Gospel, and what is revealed herein from their Lord, they would have enjoyed provisions from above them, and from beneath their feet. Some of them are righteous, but most of them are evil doers.” ("},{"_type":"quranRef","_key":"a3","reference":"5:65-66"},{"_type":"span","_key":"a4","text":")"}]},{"_type":"block","_key":"a9","style":"normal","children":[{"_type":"span","_key":"a6","text":"“If only the people of the various communities believed and maintained a righteous life, we would have showered them with blessings from the heaven and the earth.” ("},{"_type":"quranRef","_key":"a7","reference":"7:96"},{"_type":"span","_key":"a8","text":")"}]},{"_type":"block","_key":"af","style":"normal","children":[{"_type":"span","_key":"aa","text":"“God is the One who controls your happiness, or misery… God is the One who makes you rich or poor.” ("},{"_type":"quranRef","_key":"ab","reference":"53:43"},{"_type":"span","_key":"ac","text":", "},{"_type":"quranRef","_key":"ad","reference":"53:48"},{"_type":"span","_key":"ae","text":")"}]}]},{"_type":"block","_key":"at","style":"normal","children":[{"_type":"span","_key":"ag","text":"A nation that upholds God's laws is guaranteed prominence among the nations of the world, victory, prosperity, and happiness ("},{"_type":"quranRef","_key":"ah","reference":"10:62-64"},{"_type":"span","_key":"ai","text":", "},{"_type":"quranRef","_key":"aj","reference":"16:97"},{"_type":"span","_key":"ak","text":", "},{"_type":"quranRef","_key":"al","reference":"24:55"},{"_type":"span","_key":"am","text":", "},{"_type":"quranRef","_key":"an","reference":"41:30-31"},{"_type":"span","_key":"ao","text":"). On the other hand, a nation that violates God's laws incurs a miserable life ("},{"_type":"quranRef","_key":"ap","reference":"20:124"},{"_type":"span","_key":"aq","text":"). A nation that upholds God's laws is guaranteed to be a great nation. This is not a mere idealistic dream; since God is in full control ("},{"_type":"quranRef","_key":"ar","reference":"10:61"},{"_type":"span","_key":"as","text":"), His guarantees and promises are done. A nation that upholds God's laws is characterized by:"}]},{"_type":"appendixDivider","_key":"au","title":{"children":[{"_type":"span","_key":"av","text":"Nine Characteristics of a Great Nation"}]}},{"_type":"appendixBadgeList","_key":"a2f","ordered":true,"style":"badgeMd","item":"badgeBaseline","marker":"primaryCompact","content":"base","contentTag":"p","items":[{"_key":"aw","text":{"children":[{"_type":"span","_key":"ax","text":"Maximum freedom for the people","marks":["strong"]},{"_type":"span","_key":"ay","text":" — freedom of religion, freedom of expression, freedom to travel, and freedom of economy ("},{"_type":"quranRef","_key":"az","reference":"2:256"},{"_type":"span","_key":"a10","text":", "},{"_type":"quranRef","_key":"a11","reference":"10:99"},{"_type":"span","_key":"a12","text":", "},{"_type":"quranRef","_key":"a13","reference":"88:21-22"},{"_type":"span","_key":"a14","text":")."}]}},{"_key":"a15","text":{"children":[{"_type":"span","_key":"a16","text":"Guaranteed human rights for all the people","marks":["strong"]},{"_type":"span","_key":"a17","text":", regardless of their race, color, creed, social status, financial situation, or political affiliation ("},{"_type":"quranRef","_key":"a18","reference":"5:8"},{"_type":"span","_key":"a19","text":", "},{"_type":"quranRef","_key":"a1a","reference":"49:13"},{"_type":"span","_key":"a1b","text":")."}]}},{"_key":"a1c","text":{"children":[{"_type":"span","_key":"a1d","text":"Prosperity for all the people.","marks":["strong"]},{"_type":"span","_key":"a1e","text":" God's economic system is based on constant circulation of wealth, no usury, and productive investment. Non-productive economy such as gambling, lottery, and high interest loans are not permitted ("},{"_type":"quranRef","_key":"a1f","reference":"2:275-277"},{"_type":"span","_key":"a1g","text":", "},{"_type":"quranRef","_key":"a1h","reference":"59:7"},{"_type":"span","_key":"a1i","text":")."}]}},{"_key":"a1j","text":{"children":[{"_type":"span","_key":"a1k","text":"Social justice for all.","marks":["strong"]},{"_type":"span","_key":"a1l","text":" Because of the obligatory charity (Zakat), no one will go hungry or un-sheltered ("},{"_type":"quranRef","_key":"a1m","reference":"2:215"},{"_type":"span","_key":"a1n","text":", "},{"_type":"quranRef","_key":"a1o","reference":"70:24-25"},{"_type":"span","_key":"a1p","text":", "},{"_type":"quranRef","_key":"a1q","reference":"107:1-7"},{"_type":"span","_key":"a1r","text":")."}]}},{"_key":"a1s","text":{"children":[{"_type":"span","_key":"a1t","text":"A political system that is based on unanimous consensus.","marks":["strong"]},{"_type":"span","_key":"a1u","text":" Through mutual consultation and freedom of expression, one side of any given issue convinces all participants in the discussion. The end result is a unanimous agreement, not the opinion of a 51% majority rammed down the throat of the 49% minority ("},{"_type":"quranRef","_key":"a1v","reference":"42:38"},{"_type":"span","_key":"a1w","text":")."}]}},{"_key":"a1x","text":{"children":[{"_type":"span","_key":"a1y","text":"A society that upholds and maintains the highest standards of moral behavior.","marks":["strong"]},{"_type":"span","_key":"a1z","text":" There will be a strong family, no alcoholism, no illicit drugs, no illegitimate pregnancies, no abortions, and practically no divorce."}]}},{"_key":"a20","text":{"children":[{"_type":"span","_key":"a21","text":"Maximum regard for people's lives and properties.","marks":["strong"]},{"_type":"span","_key":"a22","text":" Therefore, there will be no crime against the people's lives or properties."}]}},{"_key":"a23","text":{"children":[{"_type":"span","_key":"a24","text":"Prevalence of love, courtesy, peace, and mutual respect","marks":["strong"]},{"_type":"span","_key":"a25","text":" among the people, and between this nation and other world communities ("},{"_type":"quranRef","_key":"a26","reference":"3:110"},{"_type":"span","_key":"a27","text":", "},{"_type":"quranRef","_key":"a28","reference":"60:8-9"},{"_type":"span","_key":"a29","text":")."}]}},{"_key":"a2a","text":{"children":[{"_type":"span","_key":"a2b","text":"Environmental protection","marks":["strong"]},{"_type":"span","_key":"a2c","text":" is guaranteed through conservation and prohibition of wasteful practices ("},{"_type":"quranRef","_key":"a2d","reference":"30:41"},{"_type":"span","_key":"a2e","text":")."}]}}]}]$pt$::jsonb, 'tCHFzFE3LTo', 'Appendix 36 — What Price A Great Nation'),

-- Appendix 37: Criminal Justice in Islam
('37', $pt$[{"_type":"block","_key":"a2","style":"normal","children":[{"_type":"span","_key":"a1","text":"If a thief steals a thousand dollars from you, and they put him in prison, what do you get? If the thief has a wife and children, what is their crime? Why should they be deprived of their father?"}]},{"_type":"block","_key":"a4","style":"normal","children":[{"_type":"span","_key":"a3","text":"The Quran solves this problem, as well as the problems associated with the criminal justice systems prevalent in today's world."}]},{"_type":"appendixDivider","_key":"a5","title":{"children":[{"_type":"span","_key":"a6","text":"Equivalence is the Law ["},{"_type":"quranRef","_key":"a7","reference":"2:178-179"},{"_type":"span","_key":"a8","text":"]"}]}},{"_type":"block","_key":"aa","style":"normal","children":[{"_type":"span","_key":"a9","text":"According to the Quranic criminal justice, the thief who is convicted of stealing a thousand dollars from you must work for you until you are fully paid for the thousand dollars you lost, plus any other damage and inconvenience the theft may have caused you. At the same time, the thief's innocent wife and children are not deprived of their man, and the expensive prison system is eliminated. Imprisonment is a cruel and inhumane punishment that has proven useless to all concerned."}]},{"_type":"block","_key":"as","style":"normal","children":[{"_type":"span","_key":"ab","text":"Contrary to common belief, the thief's hand shall not be cut off. Thank God for His mercy and His mathematical miracle in the Quran, we know now that the thief's hand is to be "},{"_type":"span","_key":"ac","text":"marked","marks":["em"]},{"_type":"span","_key":"ad","text":". Marking the hand of the thief is stated in "},{"_type":"quranRef","_key":"ae","reference":"5:38"},{"_type":"span","_key":"af","text":". The sura and verse numbers add up to 5+38 = 43. The other place in the Quran where “the hand is cut” is found in "},{"_type":"quranRef","_key":"ag","reference":"12:31"},{"_type":"span","_key":"ah","text":". This is where we see the women who admired Joseph so much, they “cut” their hands. Obviously, they did not sever their hands; no one can do that. The sura and verse numbers add up to 12+31 = 43, the same total as in "},{"_type":"quranRef","_key":"ai","reference":"5:38"},{"_type":"span","_key":"aj","text":". This gives mathematical confirmation that the Quranic law calls for marking the hand of the thief, not severing it. Additional mathematical confirmation is provided: 19 verses after "},{"_type":"quranRef","_key":"ak","reference":"12:31"},{"_type":"span","_key":"al","text":", we see the “cutting of the hand” again. Punishment in Submission (Islam) is based on equivalence and social pressure ("},{"_type":"quranRef","_key":"am","reference":"2:178"},{"_type":"span","_key":"an","text":", "},{"_type":"quranRef","_key":"ao","reference":"5:38"},{"_type":"span","_key":"ap","text":", "},{"_type":"quranRef","_key":"aq","reference":"24:2"},{"_type":"span","_key":"ar","text":")."}]},{"_type":"block","_key":"aw","style":"normal","children":[{"_type":"span","_key":"at","text":"The blasphemy called “Hadith & Sunna” has instituted stoning to death as the punishment for married adulterers. This is not God's law. As stated in "},{"_type":"quranRef","_key":"au","reference":"24:2"},{"_type":"span","_key":"av","text":", the punishment for adultery is whipping in public; a hundred symbolic lashes. As pointed out above, the basic punishment is social pressure and scandalizing the criminal. Whipping in public achieves this goal."}]},{"_type":"block","_key":"a12","style":"normal","children":[{"_type":"span","_key":"ax","text":"In dealing with murder, the Quran definitely discourages capital punishment ("},{"_type":"quranRef","_key":"ay","reference":"2:179"},{"_type":"span","_key":"az","text":"). “The free for the free, the slave for the slave, and the female for the female” ("},{"_type":"quranRef","_key":"a10","reference":"2:178"},{"_type":"span","_key":"a11","text":"). Due to human meanness and injustice, many people cannot even imagine what this Quranic law says. They refuse to accept the clear injunctions that strict equivalence must be observed - if a woman kills a man, or a man kills a woman, or a slave kills a free person, or a free person kills a slave, capital punishment cannot be applied. The Quran prefers that the murderer compensate the victim's family. Killing the murderer does not bring the victim back, nor does the family of the victim benefit from executing the murderer. The compensation, however, must be sufficient to be a deterrent for others. In Submission (Islam), the victim and/or the victim's family are the judges for all crimes; they decide what the punishment shall be under the supervision of a person who knows the Quran."}]}]$pt$::jsonb, 'WZ6gxmN61V4', 'Appendix 37 — Criminal Justice'),

-- Appendix 38: The Creator's Signature
('38', $pt$[{"_type":"block","_key":"a2","style":"normal","children":[{"_type":"span","_key":"a1","text":"The scriptures are not the only mathematically composed creations of God where the number 19 is the common denominator. It is profound indeed that Galileo made his famous statement: “Mathematics is the language with which God created the universe.” A plethora of scientific findings have now shown that the number 19 represents God's signature upon certain creations. This divine stamp appears throughout the universe in much the same manner as the signature of Michelangelo and Picasso identify their works. For example:"}]},{"_type":"appendixDivider","_key":"a3","title":{"children":[{"_type":"span","_key":"a4","text":"19 in Creation"}]}},{"_type":"appendixBadgeList","_key":"ag","ordered":true,"style":"badgeMd","item":"badgeBaseline","marker":"primaryCompact","content":"base","contentTag":"p","items":[{"_key":"a5","text":{"children":[{"_type":"span","_key":"a6","text":"The sun, the moon, and the earth become aligned in the same relative positions once every 19 years (see "},{"_type":"span","_key":"a7","text":"Encyclopedia Judaica","marks":["em"]},{"_type":"span","_key":"a8","text":" under “Calendar”)."}]}},{"_key":"a9","text":{"children":[{"_type":"span","_key":"aa","text":"Halley's comet, a profound heavenly phenomenon, visits our solar system every 76 years, 19×4."}]}},{"_key":"ab","text":{"children":[{"_type":"span","_key":"ac","text":"God's stamp on you and me is manifested in the fact that the human body contains 209 bones, 19×11."}]}},{"_key":"ad","text":{"children":[{"_type":"span","_key":"ae","text":"Langman's Medical Embryology","marks":["em"]},{"_type":"span","_key":"af","text":", by T. W. Sadler, is used as a textbook in most of the Medical Schools in the U.S.A. On Page 88 of the Fifth edition, we read the following statement: “In general the length of pregnancy for a full term fetus is considered to be 280 days or 40 weeks after onset of the last menstruation, or more accurately, 266 days or 38 weeks after fertilization.” The numbers 266 and 38 are both multiples of 19."}]}}]}]$pt$::jsonb, '310Gs6vO8kM', 'Appendix 38 — 19: The Creator''s Signature');

-- ── resolve the rows this run would touch ────────────────────────────────────
-- English-language Quran versions only. jsonb concatenation is a shallow merge,
-- so title, snippet, version_id, code and the existing markdown body in the
-- draft are all preserved; only body_pt and the video keys are replaced. An
-- appendix with no video has any stale video keys stripped, which is what makes
-- a re-run converge rather than accumulate.

CREATE TEMPORARY TABLE appendix_pt_targets ON COMMIT DROP AS
SELECT
  a.id,
  a.code,
  v.slug        AS version_slug,
  a.published IS NOT NULL AS is_published,
  a.draft       AS old_draft,
  CASE
    WHEN b.video_id IS NULL THEN
      (a.draft - 'video_id'::text - 'video_title'::text) || jsonb_build_object('body_pt', b.body_pt)
    ELSE
      a.draft || jsonb_build_object(
        'body_pt',     b.body_pt,
        'video_id',    b.video_id,
        'video_title', b.video_title
      )
  END AS new_draft
FROM public.editorial_appendices a
JOIN public.quran_versions   v ON v.id = a.version_id
JOIN public.languages        l ON l.id = v.lang_id
JOIN appendix_pt_backfill    b ON b.code = a.code
WHERE l.code = 'en'
  AND (:'version' = '' OR v.slug = :'version');

-- ── report ──────────────────────────────────────────────────────────────────

\echo ''
\echo '── appendix codes with no matching English row ─────────────────────────'
SELECT b.code, jsonb_array_length(b.body_pt) AS blocks
FROM appendix_pt_backfill b
WHERE NOT EXISTS (SELECT 1 FROM appendix_pt_targets t WHERE t.code = b.code)
ORDER BY b.code::int;

\echo ''
\echo '── per-row changes ────────────────────────────────────────────────────'
SELECT
  t.code,
  t.version_slug,
  CASE WHEN t.is_published THEN 'published' ELSE 'draft' END AS row_state,
  length(coalesce(t.old_draft->>'body', ''))                AS markdown_body_kept,
  coalesce(jsonb_array_length(t.old_draft->'body_pt'), 0)   AS blocks_before,
  jsonb_array_length(t.new_draft->'body_pt')                AS blocks_after,
  coalesce(t.old_draft->>'video_id', '-')                   AS video_before,
  coalesce(t.new_draft->>'video_id', '-')                   AS video_after,
  CASE WHEN t.old_draft IS DISTINCT FROM t.new_draft THEN 'CHANGES' ELSE 'unchanged' END AS verdict
FROM appendix_pt_targets t
ORDER BY t.code::int;

\echo ''
\echo '── summary ────────────────────────────────────────────────────────────'
SELECT
  (SELECT count(*) FROM appendix_pt_backfill)                                AS codes_in_script,
  count(*)                                                                   AS rows_matched,
  count(*) FILTER (WHERE old_draft IS DISTINCT FROM new_draft)               AS rows_to_update,
  count(*) FILTER (WHERE jsonb_exists(new_draft, 'video_id'))                AS rows_with_video,
  count(*) FILTER (WHERE NOT jsonb_exists(old_draft, 'body_pt'))             AS rows_without_pt_before,
  count(*) FILTER (WHERE coalesce(old_draft->>'body', '') <> '')             AS rows_keeping_markdown
FROM appendix_pt_targets;

-- ── write ───────────────────────────────────────────────────────────────────

UPDATE public.editorial_appendices a
SET draft = t.new_draft,
    updated_at = now()
FROM appendix_pt_targets t
WHERE a.id = t.id
  AND a.draft IS DISTINCT FROM t.new_draft;

\if :publish
  \echo ''
  \echo '── publishing (copying draft into the published snapshot) ──────────────'
  UPDATE public.editorial_appendices a
  SET published = a.draft,
      published_at = now(),
      updated_at = now()
  FROM appendix_pt_targets t
  WHERE a.id = t.id
    AND a.published IS DISTINCT FROM a.draft;
\else
  \echo ''
  \echo 'publish: skipped (pass -v publish=true to copy drafts into published)'
\endif

\if :apply
  COMMIT;
  \echo ''
  \echo 'APPLIED: the changes above are committed.'
\else
  ROLLBACK;
  \echo ''
  \echo 'DRY RUN: nothing was written. Re-run with -v apply=true to commit.'
\endif
